// Generated by scripts/build-permanent.mjs. Do not edit directly.
import { createKanbanController, KanbanGateway } from './remote.mjs'

function createKanbanPlugin(register) {
  const harness = { handle: register }

// Ticket File frontmatter parsing — pure functions.
//
// This file is the shared seam between the test suite (`node --test`,
// CommonJS export below) and the Plugin's Host half: `cordis_define`
// receives this file's source concatenated in front of `plugin/host.js`,
// so the `kanban*` functions must stay plain top-level declarations.
//
// Vocabulary follows CONTEXT.md: one Ticket File is
// `.dsh-kanban/tickets/<id>-<slug>.md` with frontmatter for state.

// The five Board columns; mirror of COLUMNS in plugin/client.js — keep the
// pair in lockstep (one concept, two copies; there is no shared module the
// define payload can import on both sides).
const KANBAN_COLUMNS = ['backlog', 'ready', 'in-progress', 'in-review', 'done']

// parseFrontmatter(text) → { attrs, body } | null.
// Accepts the strict form ---\n key: value … \n---; values are scalars
// (multi-line YAML is intentionally unsupported for now).
function kanbanParseFrontmatter(text) {
  if (typeof text !== 'string') return null
  const open = text.match(/^\uFEFF?---[ \t]*\r?\n/)
  if (!open) return null
  const rest = text.slice(open[0].length)
  const close = rest.match(/\r?\n---[ \t]*(?:\r?\n|$)/)
  if (!close) return null
  const attrs = {}
  for (const line of rest.slice(0, close.index).split(/\r?\n/)) {
    const m = line.match(/^\s*([A-Za-z0-9_-]+):\s*(.*)$/)
    if (!m) continue
    let value = m[2].trim()
    const q = value[0]
    if ((q === '"' || q === "'") && value[value.length - 1] === q && value.length >= 2) {
      value = value.slice(1, -1)
      if (q === '"') value = value.replace(/\\(["\\])/g, '$1')
    }
    attrs[m[1]] = value
  }
  let body = rest.slice(close.index + close[0].length)
  if (body.startsWith('---')) {
    // Closing fence consumed without its trailing newline (file ends at ---).
    body = body.slice(3).replace(/^[ \t]*\r?\n?/, '')
  }
  return { attrs, body }
}

function kanbanIdFromFileName(fileName) {
  const m = /^(kan-\d+)/i.exec(fileName || '')
  return m ? m[1].toUpperCase() : null
}

function kanbanFirstHeading(body) {
  const m = /^#\s+(.+?)\s*$/m.exec(body)
  return m ? m[1] : null
}

function kanbanBodyPreview(body, max) {
  for (const raw of body.split(/\r?\n/)) {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) continue
    if (line.length <= max) return line
    return line.slice(0, max - 1) + '…'
  }
  return ''
}

// kanbanSlug(title) → the <slug> part of a new Ticket File name: lowercase,
// alphanumerics separated by single dashes, at most 40 characters, never
// ending on a dash; 'ticket' when the title carries no usable characters.
function kanbanSlug(title) {
  const slug = String(title || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40)
    .replace(/-+$/, '')
  return slug === '' ? 'ticket' : slug
}

// kanbanNextId(ids) → the next free 'KAN-<n>' id: one above the highest
// existing KAN number, never below KAN-101. The 101 floor keeps KAN ids
// visually distinct from GitHub issue numbers (#1.. in this repo), even on
// Boards seeded with hand-numbered low ids.
function kanbanNextId(ids) {
  let max = 0
  for (const raw of ids || []) {
    const m = /^kan-(\d+)$/i.exec(String(raw == null ? '' : raw).trim())
    if (m) max = Math.max(max, parseInt(m[1], 10))
  }
  return 'KAN-' + Math.max(max + 1, 101)
}

// kanbanScalar(value) → one line-safe YAML-lite scalar: plain when safe,
// double-quoted (with \" and \\ escapes) when the value carries characters
// that would break a flat scalar or a strict YAML reader. Newlines are
// folded to single spaces first — scalars always stay on one line.
function kanbanScalar(value) {
  const text = String(value).replace(/\s*\r?\n\s*/g, ' ')
  if (text !== '' && text === text.trim() && !/[:#"'\\\n\r]/.test(text)) return text
  return '"' + text.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"'
}

// The documented frontmatter keys (CONTEXT.md, Ticket File), in canonical
// write order. Keys outside this set are never written by the serializer.
const KANBAN_KEY_ORDER = [
  'id',
  'title',
  'column',
  'queued',
  'blocked',
  'issue',
  'reviewUrl',
  'base',
  'baseBranch',
  'branch',
  'worktreePath',
  'sessionId',
  'bounces',
  'mergeSha',
]

// serializeTicketFile(attrs, body) → the full Ticket File text. Only the
// documented keys are written; undefined/null values are omitted, an empty
// string is written as the quoted empty scalar "". The body always ends
// with exactly one newline.
function serializeTicketFile(attrs, body) {
  const lines = []
  for (const key of KANBAN_KEY_ORDER) {
    const value = attrs[key]
    if (value === undefined || value === null) continue
    lines.push(key + ': ' + kanbanScalar(value))
  }
  let text = '---\n' + lines.join('\n') + '\n---\n' + String(body || '')
  if (!text.endsWith('\n')) text += '\n'
  return text
}

// kanbanFrontmatterParts(text) → { head, lines, sep, tail } | null, the one
// place that finds the frontmatter boundaries. `head` is the opening fence
// including its line ending, `lines` the frontmatter lines without endings,
// `sep` the detected line-ending style (LF or CRLF), `tail` everything from
// the newline before the closing fence onward. A caller that re-joins
// `lines` with `sep` leaves the rest of the file byte-identical.
function kanbanFrontmatterParts(text) {
  const open = text.match(/^\uFEFF?---[ \t]*\r?\n/)
  if (open === null) return null
  const rest = text.slice(open[0].length)
  const close = rest.match(/\r?\n---[ \t]*(?:\r?\n|$)/)
  if (close === null) return null
  return {
    head: open[0],
    lines: rest.slice(0, close.index).split(/\r?\n/),
    sep: open[0].endsWith('\r\n') ? '\r\n' : '\n',
    tail: rest.slice(close.index),
    fenceLength: close[0].length,
  }
}

// kanbanSetAttr(text, key, value) → the same Ticket File with exactly one
// frontmatter line rewritten (or inserted before the closing fence, or
// removed when value is empty/null). Everything else — key order, quoting,
// line endings, and the whole body — stays byte-identical, which is what
// makes a move touch only the `column` field. Null when there is no fence.
function kanbanSetAttr(text, key, value) {
  const parts = kanbanFrontmatterParts(text)
  if (parts === null) return null
  const matcher = new RegExp('^\\s*' + key + ':')
  const index = parts.lines.findIndex((line) => matcher.test(line))
  if (value === undefined || value === null || value === '') {
    if (index === -1) return text
    parts.lines.splice(index, 1)
  } else {
    const line = key + ': ' + kanbanScalar(value)
    if (index === -1) parts.lines.push(line)
    else parts.lines[index] = line
  }
  return parts.head + parts.lines.join(parts.sep) + parts.tail
}

// kanbanSetBody(text, body) → the same Ticket File with the body (everything
// after the closing fence) replaced; frontmatter stays byte-identical,
// including its line endings. Used by ticket.update so untouched fields
// cannot drift. Null when no fence.
function kanbanSetBody(text, body) {
  const parts = kanbanFrontmatterParts(text)
  if (parts === null) return null
  let head = parts.head + parts.lines.join(parts.sep) + parts.tail.slice(0, parts.fenceLength)
  if (!head.endsWith('\n')) head += parts.sep
  let next = head + String(body || '')
  if (!next.endsWith('\n')) next += '\n'
  return next
}

function kanbanApplyRemoteText(text, remote) {
  if (!remote || typeof remote.title !== 'string' || typeof remote.body !== 'string') {
    throw new Error('Remote Issue text is required')
  }
  let next = kanbanSetAttr(text, 'title', remote.title)
  if (next === null) throw new Error('not-a-ticket-file')
  next = kanbanSetBody(next, remote.body)
  if (next === null) throw new Error('not-a-ticket-file')
  return next
}

function kanbanNormalizeColumn(value) {
  const c = String(value || '').trim().toLowerCase()
  return KANBAN_COLUMNS.includes(c) ? c : 'backlog'
}

// parseTicketFile(fileName, text) → card data for one Board card, or null
// when the file is not a Ticket File.
function parseTicketFile(fileName, text) {
  const fm = kanbanParseFrontmatter(text)
  if (fm === null) return null
  const id = (fm.attrs.id || '').trim() || kanbanIdFromFileName(fileName)
  if (id === null || id === '') return null
  return {
    id: id.toUpperCase(),
    title: (fm.attrs.title || '').trim() || kanbanFirstHeading(fm.body) || fileName,
    column: kanbanNormalizeColumn(fm.attrs.column),
    queued: (fm.attrs.queued || '').trim(),
    blocked: (fm.attrs.blocked || '').trim(),
    issue: (fm.attrs.issue || '').trim(),
    reviewUrl: (fm.attrs.reviewUrl || '').trim(),
    base: fm.attrs.base === 'head' ? 'head' : 'remote',
    branch: (fm.attrs.branch || '').trim(),
    baseBranch: (fm.attrs.baseBranch || '').trim(),
    mergeSha: (fm.attrs.mergeSha || '').trim(),
    worktreePath: (fm.attrs.worktreePath || fm.attrs.worktree || '').trim(),
    sessionId: (fm.attrs.sessionId || fm.attrs.session || '').trim(),
    body: fm.body,
    preview: kanbanBodyPreview(fm.body, 160),
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    parseTicketFile,
    KANBAN_COLUMNS,
    kanbanSlug,
    kanbanNextId,
    serializeTicketFile,
    kanbanSetAttr,
    kanbanSetBody,
    kanbanApplyRemoteText,
  }
}

// Board settings model — pure functions.
//
// This file is the tested seam for per-Workspace settings. Dynamic Host
// Packages concatenate it before plugin/host.js, so declarations stay plain
// JavaScript and top-level.

const KANBAN_DEFAULT_WIP_LIMIT = 3

function kanbanParseWipLimit(value) {
  if (typeof value !== 'number' && typeof value !== 'string') return null
  if (typeof value === 'string' && value.trim() === '') return null
  const parsed = Number(value)
  return Number.isInteger(parsed) && parsed > 0 ? parsed : null
}

function kanbanWorkspaceSettings(workspace, stored) {
  const storedLimit = stored === undefined ? null : kanbanParseWipLimit(stored.wipLimit)
  return {
    path: workspace.path,
    wipLimit: storedLimit === null ? KANBAN_DEFAULT_WIP_LIMIT : storedLimit,
    autopilot: stored !== undefined && stored.autopilot === true,
  }
}

function kanbanWorkspaceSettingEntries(workspaces, storedFor) {
  return workspaces.map((workspace) => {
    const workspaceId = String(workspace.id)
    return {
      workspaceId,
      settings: kanbanWorkspaceSettings(workspace, storedFor(workspaceId)),
    }
  })
}

// storageDomain calls valueSchema.parse at the durable boundary. Dynamic Host
// Packages cannot import zod, so this small schema implements that exact face.
// It returns owned data and rejects malformed durable records.
const kanbanSettingsRecordSchema = {
  parse(value) {
    if (value === null || typeof value !== 'object' || Array.isArray(value)) {
      throw new Error('Board Workspace settings must be an object')
    }
    if (typeof value.path !== 'string' || value.path === '') {
      throw new Error('Board Workspace settings require a path')
    }
    if (typeof value.wipLimit !== 'number' || kanbanParseWipLimit(value.wipLimit) === null) {
      throw new Error('Board Workspace settings require a positive whole-number WIP limit')
    }
    if (value.autopilot !== undefined && typeof value.autopilot !== 'boolean') {
      throw new Error('Board Workspace settings require an Autopilot boolean')
    }
    return { path: value.path, wipLimit: value.wipLimit, autopilot: value.autopilot === true }
  },
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    KANBAN_DEFAULT_WIP_LIMIT,
    kanbanParseWipLimit,
    kanbanSettingsRecordSchema,
    kanbanWorkspaceSettingEntries,
    kanbanWorkspaceSettings,
  }
}

// WIP queue model — pure functions.
//
// This file is the tested seam for issue #5's queue decisions. Dynamic Host
// Packages concatenate it before plugin/host.js, so declarations stay plain
// JavaScript and top-level. Every function reads and returns parsed card
// data (parseTicketFile output) — no file or storage access here.
//
// Vocabulary follows CONTEXT.md: a Ticket dragged into In Progress past the
// Workspace's WIP limit is queued — it sits In Progress with a `queued`
// frontmatter value (the UTC instant it was queued), owns no Agent Session,
// and does not count toward the limit. When a running Ticket leaves In
// Progress, the earliest queued Ticket spawns.

// kanbanQueuedInstant(value) → epoch millis of a `queued` frontmatter value
// (a UTC ISO instant written by the Board), or null when absent or not a
// valid instant. One meaning, one form: the Board writes ISO only.
function kanbanQueuedInstant(value) {
  const text = String(value === undefined || value === null ? '' : value).trim()
  if (text === '') return null
  const millis = Date.parse(text)
  return Number.isNaN(millis) ? null : millis
}

// kanbanIsQueued(card) → true only for a Ticket sitting In Progress with a
// recorded queued instant. A `queued` value on a card in any other column is
// stale hand-editing and reads as not queued.
function kanbanIsQueued(card) {
  return card.column === 'in-progress' && kanbanQueuedInstant(card.queued) !== null
}

// kanbanRunningTickets(tickets) → the In Progress Tickets that own an Agent
// Session slot. Queued Tickets wait and never count toward the limit.
function kanbanRunningTickets(tickets) {
  return (tickets || []).filter((ticket) => ticket.column === 'in-progress' && !kanbanIsQueued(ticket))
}

function kanbanTicketNumber(ticket) {
  const m = /^kan-(\d+)$/i.exec(String((ticket && ticket.id) || '').trim())
  return m === null ? Number.MAX_SAFE_INTEGER : parseInt(m[1], 10)
}

// kanbanQueuedTickets(tickets) → queued Tickets, earliest queued first. The
// recorded instant orders the queue; the KAN number breaks exact ties. This
// order survives DSH restarts because it is read back from Ticket Files.
function kanbanQueuedTickets(tickets) {
  return (tickets || [])
    .filter(kanbanIsQueued)
    .sort((a, b) => {
      const byInstant = kanbanQueuedInstant(a.queued) - kanbanQueuedInstant(b.queued)
      if (byInstant !== 0) return byInstant
      return kanbanTicketNumber(a) - kanbanTicketNumber(b)
    })
}

// kanbanQueueAdmission({ tickets, wipLimit }) → the decision for a Ready →
// In Progress move: { action: 'queue' } when running Tickets already reach
// the limit, or when queued Tickets already wait (the move joins the back of
// the queue instead of jumping it), { action: 'spawn' } when a slot is free
// and the queue is empty. The caller has already established the move
// targets an unstarted Ready Ticket.
function kanbanQueueAdmission({ tickets, wipLimit }) {
  const limit = typeof wipLimit === 'number' && wipLimit > 0 ? wipLimit : 1
  const running = kanbanRunningTickets(tickets).length
  const waiting = kanbanQueuedTickets(tickets).length
  return running >= limit || waiting > 0 ? { action: 'queue' } : { action: 'spawn' }
}

// kanbanQueuePlan({ tickets, wipLimit }) → the queued Ticket to auto-spawn
// now, or undefined when the queue is empty or the limit is still reached.
// The Board calls this after any move that can free a slot.
function kanbanQueuePlan({ tickets, wipLimit }) {
  const limit = typeof wipLimit === 'number' && wipLimit > 0 ? wipLimit : 1
  if (kanbanRunningTickets(tickets).length >= limit) return undefined
  return kanbanQueuedTickets(tickets)[0]
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    kanbanQueuedInstant,
    kanbanIsQueued,
    kanbanQueuedTickets,
    kanbanRunningTickets,
    kanbanQueueAdmission,
    kanbanQueuePlan,
  }
}

// Ticket execution module — pure orchestration behind one tested interface.
//
// Dynamic Host Packages concatenate this file before plugin/host.js. The
// production Host supplies adapters for Git, files, Agent Sessions, and
// storageDomain. Tests supply adapters at the same seam.

const KANBAN_WORKTREE_IGNORE = '.dsh-kanban/worktrees/'

function kanbanExecutionInput(request) {
  if (request === null || typeof request !== 'object') throw new Error('Ticket execution request required')
  const workspaceId = String(request.workspaceId || '').trim()
  const workspacePath = String(request.workspacePath || '').replace(/\/+$/, '')
  const ticketId = String(request.ticketId || '').trim().toUpperCase()
  const ticketSlug = String(request.ticketSlug || '').trim().toLowerCase()
  const ticketText = String(request.ticketText || '')
  const issueUrl = String(request.issueUrl || '').trim()
  const baseMode = request.baseMode === 'head' ? 'head' : 'remote'
  const autopilot = request.autopilot === true
  if (workspaceId === '') throw new Error('Ticket execution requires a Workspace id')
  if (workspacePath === '') throw new Error('Ticket execution requires a Workspace path')
  if (!/^KAN-\d+$/.test(ticketId)) throw new Error('Ticket execution requires a KAN id')
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(ticketSlug) || ticketSlug.length > 40) {
    throw new Error('Ticket execution requires a valid Ticket slug')
  }
  return { workspaceId, workspacePath, ticketId, ticketSlug, ticketText, issueUrl, baseMode, autopilot }
}

function kanbanEnsureIgnoreLine(text, line) {
  const lines = String(text || '').split(/\r?\n/)
  if (lines.includes(line) || (line === KANBAN_WORKTREE_IGNORE && lines.includes('.dsh-kanban/'))) return String(text || '')
  let next = String(text || '')
  if (next !== '' && !next.endsWith('\n')) next += '\n'
  return next + line + '\n'
}

function kanbanExecutionBrief(ticketText, branch, workspacePath, worktreePath, remote, issueUrl) {
  const rules = [
    '- Work only on branch `' + branch + '`.',
    '- Work only inside the Worktree `' + worktreePath + '`.',
    '- Never touch the main checkout `' + workspacePath + '`.',
    '- Commit completed work to `' + branch + '`.',
  ]
  if (remote && (remote.platform === 'github' || remote.platform === 'gitlab')) {
    rules.push('- Push the Ticket branch with `git push -u ' + remote.remote + ' ' + branch + '`.')
    rules.push(remote.platform === 'github'
      ? '- Create its GitHub PR with `gh pr create` after pushing.'
      : '- Create its GitLab MR with `glab mr create` after pushing.')
    if (issueUrl) rules.push('- Reference the linked Issue `' + issueUrl + '` in the PR/MR description.')
  }
  return [
    'Complete the Ticket below.',
    '',
    'Board rules:',
    ...rules,
    '',
    'Ticket File:',
    '',
    ticketText,
  ].join('\n')
}

// One Host command boundary shared by Git and remote platform CLIs.
async function kanbanRunHostCommand(shell, workdir, args, options = {}) {
  const quote = (value) => "'" + String(value).replace(/'/g, "'\\''") + "'"
  const result = await shell.run(shell.resolve({
    command: args.map(quote).join(' '),
    workdir,
    timeoutMs: options.timeoutMs || 30000,
    stdoutMaxBytes: options.stdoutMaxBytes || 262144,
  }))
  const allowed = options.allowedExitCodes || [0]
  if (!allowed.includes(result.exitCode)) {
    throw new Error(result.stderr.text.trim() || result.stdout.text.trim() || 'command failed')
  }
  return { exitCode: result.exitCode, text: result.stdout.text, truncated: result.stdout.truncated === true }
}

// One Host Git boundary shared by execution, watching, and completion.
function kanbanRunHostGit(shell, workdir, args, options = {}) {
  return kanbanRunHostCommand(shell, workdir, ['git', ...args], options)
}

// Bind the dynamic Host capabilities to the Ticket execution interface.
function kanbanHostExecutionAdapter(deps) {
  const workspacePath = deps.workspace.path.replace(/\/+$/, '')
  const runGit = async (args) => {
    const result = await kanbanRunHostGit(deps.shell, deps.workspace.path, args, { timeoutMs: 120000 })
    return result.text.trim()
  }
  return {
    runGit,
    detectRemote: () => {
      const command = (args, allowed = [0]) => kanbanRunHostCommand(deps.shell, deps.workspace.path, args, {
        allowedExitCodes: allowed, timeoutMs: 30000,
      })
      return kanbanDetectRemote(
        (args, allowed = [0]) => kanbanRunHostGit(deps.shell, deps.workspace.path, args, {
          allowedExitCodes: allowed, timeoutMs: 30000,
        }),
        (location) => kanbanProbeRemotePlatform(location, command),
      )
    },
    async readIgnore() {
      const target = await deps.fs.resolve(workspacePath + '/.gitignore')
      const info = await deps.fs.stat(target)
      if (info === undefined) return ''
      if (info.type !== 'file') throw new Error('.gitignore is not a file')
      return deps.fs.readText(target)
    },
    async writeIgnore(text) {
      const target = await deps.fs.resolve(workspacePath + '/.gitignore')
      await deps.fs.writeText(target, text)
    },
    setTicketAttr: deps.setTicketAttr,
    persistTicket: (text) => deps.fs.writeText(deps.loaded.target, text),
    persistLinkage: (key, linkage) => deps.executionTable.put(key, linkage),
    deleteLinkage: (key) => deps.executionTable.delete(key),
    async createSession(spec) {
      const selection = deps.agentDefaultModel.currentSelection()
      const preset = await deps.agentPresets.resolve()
      const handle = await deps.agents.create({
        sessionId: spec.sessionId,
        meta: { cwd: spec.cwd, agentPreset: preset.id },
        agentOptions: { provider: selection.provider, model: selection.model },
        setup: async (agentCtx) => {
          await deps.agentPresets.mount(agentCtx, preset.id)
          // Setup runs before publication, so no observer can drive the Agent
          // Session before its Board-owned Autopilot policy is pinned.
          if (spec.autopilot) {
            agentCtx.agent.session.append('sandbox/mode', { mode: 'workspace-write' })
            agentCtx.agent.session.append('approval/policy', { policy: 'never' })
          }
        },
      })
      if (deps.rememberSession) deps.rememberSession(handle)
      await handle.agent.whenIdle()
      return { id: handle.agent.id, agent: handle.agent, dispose: () => handle.dispose() }
    },
    disposeSession: (session) => session.dispose(),
    async followup(session, brief) {
      session.agent.followup({
        id: 'kanban-brief-' + session.id,
        role: 'user',
        content: [{ type: 'text', text: brief }],
        source: { kind: 'plugin', plugin: 'dsh-kanban' },
      })
    },
  }
}

async function kanbanRemoteDefault(adapter) {
  const remotes = String(await adapter.runGit(['remote']))
    .split(/\r?\n/)
    .map((value) => value.trim())
    .filter((value) => value !== '')
  if (remotes.length === 0) throw new Error('Workspace has no git remote')
  const remote = remotes[0]
  if (!/^[A-Za-z0-9._-]+$/.test(remote)) throw new Error('Workspace git remote name is unsafe')
  const prefix = remote + '/'
  let branch
  try {
    const symbolic = String(
      await adapter.runGit(['symbolic-ref', '--quiet', '--short', 'refs/remotes/' + remote + '/HEAD']),
    ).trim()
    if (symbolic.startsWith(prefix) && symbolic.length > prefix.length) branch = symbolic.slice(prefix.length)
  } catch {
    // A remote can declare HEAD without a local refs/remotes/<name>/HEAD.
  }
  if (branch === undefined) {
    const description = String(await adapter.runGit(['remote', 'show', remote]))
    const match = /^\s*HEAD branch:\s*(\S+)\s*$/m.exec(description)
    if (match !== null) branch = match[1]
  }
  if (branch === undefined) throw new Error('Workspace remote default branch is unavailable')
  if (!/^[A-Za-z0-9._/-]+$/.test(branch) || branch.includes('..')) {
    throw new Error('Workspace remote default branch is unsafe')
  }
  await adapter.runGit(['fetch', '--quiet', remote, branch])
  return remote + '/' + branch
}

let kanbanExecutionSequence = 0

async function kanbanStartTicketExecution(request, adapter) {
  const input = kanbanExecutionInput(request)
  const branch = 'kanban/' + input.ticketId + '-' + input.ticketSlug
  const relativeWorktreePath = '.dsh-kanban/worktrees/' + input.ticketSlug
  const worktreePath = input.workspacePath + '/' + relativeWorktreePath
  // A released Ticket can start again; its earlier session stays persisted.
  const sessionId = ('kanban-' + input.workspaceId + '-' + input.ticketId + '-' + Date.now() + '-' + (++kanbanExecutionSequence))
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, '-')
  const linkageKey = input.workspaceId + '/' + input.ticketId
  const linkage = {
    workspaceId: input.workspaceId,
    ticketId: input.ticketId,
    sessionId,
    worktreePath,
    branch,
    // The commit the branch spawns from; the watch loop compares the branch
    // head against it to decide whether the branch has commits.
    baseSha: '',
  }
  let linkedTicketText = input.ticketText
  const linkedAttrs = [
    ['column', 'in-progress'],
    ['branch', branch],
    ['worktreePath', worktreePath],
    ['sessionId', sessionId],
    // Spawning clears the issue #5 queue marker; removing an absent key is a
    // no-op, so non-queued starts keep their text byte-identical here.
    ['queued', null],
  ]
  for (const [key, value] of linkedAttrs) {
    linkedTicketText = adapter.setTicketAttr(linkedTicketText, key, value)
    if (linkedTicketText === null) throw new Error('Ticket File frontmatter is invalid')
  }

  const ignore = await adapter.readIgnore()
  const nextIgnore = kanbanEnsureIgnoreLine(ignore, KANBAN_WORKTREE_IGNORE)
  if (nextIgnore !== ignore) await adapter.writeIgnore(nextIgnore)
  const localOnly = String(await adapter.runGit(['remote'])).trim() === ''
  const completionRemote = typeof adapter.detectRemote === 'function'
    ? await adapter.detectRemote() : { platform: 'none', remote: '', url: '' }
  const baseRef = input.baseMode === 'head' || localOnly ? 'HEAD' : await kanbanRemoteDefault(adapter)
  if (localOnly) {
    const baseBranch = String(await adapter.runGit(['symbolic-ref', '--short', 'HEAD'])).trim()
    linkedTicketText = adapter.setTicketAttr(linkedTicketText, 'baseBranch', baseBranch)
  }
  linkage.baseSha = await adapter.runGit(['rev-parse', baseRef])
  let worktreeCreated = false
  let session
  let ticketPersisted = false
  let linkagePersisted = false
  try {
    await adapter.runGit(['worktree', 'add', '-b', branch, relativeWorktreePath, baseRef])
    worktreeCreated = true
    session = await adapter.createSession({ sessionId, cwd: worktreePath, autopilot: input.autopilot })
    await adapter.persistTicket(linkedTicketText)
    ticketPersisted = true
    await adapter.persistLinkage(linkageKey, linkage)
    linkagePersisted = true
    await adapter.followup(session, kanbanExecutionBrief(
      input.ticketText, branch, input.workspacePath, worktreePath, completionRemote, input.issueUrl,
    ))
    return linkage
  } catch (error) {
    const cleanupErrors = []
    const clean = async (operation) => {
      try {
        await operation()
      } catch (cleanupError) {
        cleanupErrors.push(String((cleanupError && cleanupError.message) || cleanupError))
      }
    }
    if (ticketPersisted) await clean(() => adapter.persistTicket(input.ticketText))
    if (linkagePersisted) await clean(() => adapter.deleteLinkage(linkageKey))
    if (session !== undefined) await clean(() => adapter.disposeSession(session))
    if (worktreeCreated) {
      await clean(() => adapter.runGit(['worktree', 'remove', '--force', relativeWorktreePath]))
      await clean(() => adapter.runGit(['branch', '-D', branch]))
    }
    if (cleanupErrors.length > 0) {
      throw new Error(
        String((error && error.message) || error) + '; rollback failed: ' + cleanupErrors.join('; '),
      )
    }
    throw error
  }
}

const kanbanExecutionRecordSchema = {
  parse(value) {
    if (value === null || typeof value !== 'object' || Array.isArray(value)) {
      throw new Error('Ticket execution linkage must be an object')
    }
    const fields = ['workspaceId', 'ticketId', 'sessionId', 'worktreePath', 'branch']
    for (const field of fields) {
      if (typeof value[field] !== 'string' || value[field] === '') {
        throw new Error('Ticket execution linkage requires ' + field)
      }
    }
    return {
      workspaceId: value.workspaceId,
      ticketId: value.ticketId,
      sessionId: value.sessionId,
      worktreePath: value.worktreePath,
      branch: value.branch,
      // Optional: linkage records stored before the watch loop (issue #6)
      // carry no spawn sha; the watch loop treats a missing one as no commits.
      baseSha: typeof value.baseSha === 'string' ? value.baseSha : '',
    }
  },
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    KANBAN_WORKTREE_IGNORE,
    kanbanEnsureIgnoreLine,
    kanbanExecutionBrief,
    kanbanStartTicketExecution,
  }
}

// Board session-watch model — pure functions over one observed session signal.
//
// This file is the tested seam for issue #6's watch loop. Dynamic Host
// Packages concatenate it before plugin/host.js, so declarations stay plain
// JavaScript and top-level. The Host wiring (plugin/host.js) subscribes to
// the real DSH events and forwards each one here as a signal request; this
// module owns the decision, the Host adapter owns every side effect.
//
// Vocabulary follows CONTEXT.md: an Attention Badge marks a session that
// awaits approval, errored, or finished; a session idling after a completed
// turn with commits on its kanban branch moves its Ticket to In Review.

// kanbanHandleSessionSignal(request, adapter) →
//   { attention, moved } — `attention` is the next Attention Badge state for
//   the session ('approval' | 'error' | 'finished', null clears, undefined
//   leaves it unchanged); `moved` reports an automatic In Review transition.
//
// request — one observed session signal:
//   { signal: 'status', sessionId, status: 'idle' | 'running', reasonKind }
//   { signal: 'turn-end', sessionId, reason }
//   { signal: 'approval-asked', sessionId }
//   { signal: 'approval-decided', sessionId }
//   { signal: 'agent-error', sessionId }
//
// adapter (bound by the Host; faked by tests):
//   linkageFor(sessionId) → linkage | undefined
//   linkedTicketColumn(linkage) → column string
//   branchHasCommits(linkage) → boolean
//   moveTicketToInReview(linkage) → writes column: in-review; false declines
//     a stale completion after a Bounce or another state change.
async function kanbanHandleSessionSignal(request, adapter) {
  const sessionId = String((request && request.sessionId) || '')
  const signal = request && request.signal
  const attention = kanbanAttentionForSignal(request)
  let moved = false
  if (signal === 'status' && request.status === 'idle' && request.reasonKind === 'completed') {
    const linkage = await adapter.linkageFor(sessionId)
    if (linkage !== undefined && (await adapter.linkedTicketColumn(linkage)) === 'in-progress') {
      if (await adapter.branchHasCommits(linkage)) {
        moved = (await adapter.moveTicketToInReview(linkage)) !== false
      }
    }
  }
  return { attention, moved }
}

const KANBAN_STALLED_REASONS = ['error', 'interrupted', 'aborted', 'blocked', 'max-tokens']

function kanbanAttentionForSignal(request) {
  if (request === null || typeof request !== 'object') return undefined
  if (request.signal === 'status') {
    if (request.status !== 'idle') return null
    if (request.reasonKind === 'completed') return 'finished'
    if (KANBAN_STALLED_REASONS.includes(request.reasonKind)) return 'error'
    return null
  }
  if (request.signal === 'turn-end') {
    const kind = request.reason && request.reason.kind
    if (kind === 'completed') return 'finished'
    if (KANBAN_STALLED_REASONS.includes(kind)) return 'error'
    return null
  }
  if (request.signal === 'approval-asked') return 'approval'
  if (request.signal === 'approval-decided') return null
  if (request.signal === 'agent-error') return 'error'
  return undefined
}

// kanbanBranchHasCommits(linkage, runGit) → whether the Ticket's kanban
// branch has advanced past the sha it was spawned from. The spawn sha
// (`baseSha`, recorded at execution start) is the source of truth: a remote
// default branch can move and a `base: head` branch starts from local
// commits, so anything derived from a live ref would lie. A deleted branch
// or a missing spawn sha fails closed (no commits).
async function kanbanBranchHasCommits(linkage, runGit) {
  if (linkage === null || typeof linkage !== 'object') return false
  const branch = String(linkage.branch || '')
  const baseSha = String(linkage.baseSha || '')
  if (branch === '' || baseSha === '') return false
  try {
    const head = String(await runGit(['rev-parse', '--verify', 'refs/heads/' + branch])).trim()
    return head !== '' && head !== baseSha
  } catch {
    return false
  }
}

// kanbanWatchSummary(linkages, attentionFor) → { count, tickets } — the
// aggregate behind the sidebar Kanban button: every linked Ticket whose
// session currently carries an Attention Badge, sorted by Ticket id for a
// stable list. `attentionFor(sessionId)` returns the live badge state.
function kanbanWatchSummary(linkages, attentionFor) {
  const tickets = []
  for (const linkage of Array.isArray(linkages) ? linkages : []) {
    if (linkage === null || typeof linkage !== 'object') continue
    const attention = attentionFor(String(linkage.sessionId || ''))
    if (attention !== 'approval' && attention !== 'error' && attention !== 'finished') continue
    tickets.push({
      workspaceId: String(linkage.workspaceId || ''),
      ticketId: String(linkage.ticketId || ''),
      attention,
    })
  }
  tickets.sort((a, b) => (a.ticketId < b.ticketId ? -1 : a.ticketId > b.ticketId ? 1 : 0))
  return { count: tickets.length, tickets }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    kanbanHandleSessionSignal,
    kanbanAttentionForSignal,
    kanbanBranchHasCommits,
    kanbanWatchSummary,
  }
}

// ticket.bounce orchestration. Concatenate after frontmatter.js and before
// host.js. Ticket Files own the history; execution linkage is unchanged.
async function kanbanBounceTicket(request, adapter) {
  const comment = request.comment
  if (typeof comment !== 'string' || comment.trim() === '') throw new Error('comment required')
  const card = parseTicketFile(request.file, request.ticketText)
  if (card === null) throw new Error('not-a-ticket-file')
  if (card.column !== 'in-review') throw new Error('ticket-not-in-review')
  if (card.sessionId === '' || card.branch === '' || card.worktreePath === '') {
    throw new Error('ticket-not-started')
  }
  const agent = adapter.liveAgent(card.sessionId)
  if (agent === undefined) throw new Error('session-not-live')
  if (agent.status !== 'idle') throw new Error('session-not-idle')

  // JSON is encoded inside one YAML-lite scalar. Escaped newlines preserve
  // multiline comments without changing the Ticket description or its editor.
  const raw = kanbanParseFrontmatter(request.ticketText).attrs.bounces
  let history = []
  if (raw !== undefined && raw !== '') {
    try { history = JSON.parse(raw) } catch { throw new Error('invalid-bounce-history') }
    if (!Array.isArray(history) || history.some((entry) =>
      entry === null || typeof entry !== 'object' ||
      typeof entry.comment !== 'string' || typeof entry.at !== 'string')) {
      throw new Error('invalid-bounce-history')
    }
  }
  history.push({ at: request.at, comment })
  let text = kanbanSetAttr(request.ticketText, 'column', 'in-progress')
  text = kanbanSetAttr(text, 'queued', null)
  text = kanbanSetAttr(text, 'bounces', JSON.stringify(history))
  await adapter.persistTicket(text)
  try {
    if (adapter.liveAgent(card.sessionId) !== agent || agent.status !== 'idle') {
      throw new Error('session-no-longer-idle')
    }
    adapter.steer(agent, comment)
  } catch (error) {
    try { await adapter.persistTicket(request.ticketText) } catch (rollbackError) {
      throw new Error(String(error.message || error) + '; rollback failed: ' + String(rollbackError.message || rollbackError))
    }
    throw error
  }
  return { file: request.file, column: 'in-progress', sessionId: card.sessionId }
}

// Local and remote completion orchestration, called through Board RPCs.
// Concatenate after frontmatter.js and before host.js. Plain JavaScript only.

function kanbanRemoteLocation(remoteUrl) {
  const url = String(remoteUrl || '').trim()
  let match = /^[A-Za-z][A-Za-z0-9+.-]*:\/\/(?:[^/@]+@)?([^/:]+)(?::\d+)?\/(.+)$/.exec(url)
  if (match === null) match = /^(?:[^/@:]+@)?([^/:]+):(.+)$/.exec(url)
  if (match === null) return { host: '', repo: '' }
  return {
    host: match[1].toLowerCase(),
    repo: match[1] + '/' + match[2].replace(/^\/+|\/+$/g, '').replace(/\.git$/, ''),
  }
}

// Detect the supported remote used for completion. `origin` wins when several
// supported remotes exist, because Ticket branches are normally pushed there.
async function kanbanDetectRemote(git, probe) {
  const names = String((await git(['remote'])).text || '').split(/\r?\n/)
    .map((name) => name.trim()).filter((name) => name !== '')
  const ordered = names.includes('origin') ? ['origin', ...names.filter((name) => name !== 'origin')] : names
  for (const remote of ordered) {
    if (!/^[A-Za-z0-9._-]+$/.test(remote)) continue
    const result = await git(['remote', 'get-url', remote], [0, 2, 128])
    if (result.exitCode !== 0) continue
    const url = String(result.text || '').trim()
    const location = kanbanRemoteLocation(url)
    if (/(^|\.)github(?:\.|$)/.test(location.host)) return { platform: 'github', remote, url, repo: location.repo }
    if (/(^|\.)gitlab(?:\.|$)/.test(location.host)) return { platform: 'gitlab', remote, url, repo: location.repo }
    if (probe !== undefined && location.host !== '') {
      const platform = await probe(location)
      if (platform === 'github' || platform === 'gitlab') return { platform, remote, url, repo: location.repo }
    }
  }
  return { platform: 'none', remote: '', url: '', repo: '' }
}

async function kanbanProbeRemotePlatform(location, command) {
  const github = await command(['gh', 'auth', 'status', '--hostname', location.host], [0, 1, 127])
  if (github.exitCode === 0) return 'github'
  const gitlab = await command(['glab', 'auth', 'status', '--hostname', location.host], [0, 1, 127])
  return gitlab.exitCode === 0 ? 'gitlab' : 'none'
}

// Bind one supported platform CLI to the shared remote-completion interface.
// A missing PR/MR is ordinary while an Agent Session is still finishing.
function kanbanRemotePlatformAdapter(remote, command) {
  if (!remote || (remote.platform !== 'github' && remote.platform !== 'gitlab')) {
    throw new Error('unsupported-remote-platform')
  }
  return {
    async review(branch, recordedUrl) {
      const gitlabId = /\/merge_requests\/(\d+)(?:[/?#]|$)/.exec(String(recordedUrl || ''))
      const reference = recordedUrl === '' || recordedUrl === undefined
        ? branch : remote.platform === 'gitlab' && gitlabId !== null ? gitlabId[1] : recordedUrl
      const args = remote.platform === 'github'
        ? ['gh', 'pr', 'view', reference, '--repo', remote.repo, '--json', 'url,state,mergedAt,headRefName']
        : ['glab', 'mr', 'view', reference, '--repo', remote.repo, '--output', 'json']
      const result = await command(args, [0, 1])
      if (!result || result.exitCode !== 0 || String(result.text || '').trim() === '') return null
      let value
      try { value = JSON.parse(result.text) } catch { throw new Error(remote.platform + '-review-invalid-json') }
      const url = String(remote.platform === 'github' ? value.url : value.web_url || '')
      let state = String(value.state || '').toLowerCase()
      if (state === 'opened') state = 'open'
      if (url === '') throw new Error(remote.platform + '-review-url-missing')
      const merged = state === 'merged' || Boolean(remote.platform === 'github' ? value.mergedAt : value.merged_at)
      return { url, state: merged ? 'merged' : state, merged }
    },
  }
}

function kanbanRemotePollDelay(attempt) {
  return Math.min(300000, 15000 * (2 ** Math.max(0, Number(attempt) || 0)))
}

async function kanbanCompleteRemoteTicket(request, adapter) {
  const card = adapter.parseTicketFile(request.file, request.text)
  if (!card || card.column !== 'in-review') throw new Error('ticket-not-in-review')
  const slug = /^kan-\d+-([a-z0-9-]+)\.md$/i.exec(request.file)
  const root = request.workspacePath.replace(/\/+$/, '')
  if (!slug || card.branch !== 'kanban/' + card.id + '-' + slug[1] ||
      card.worktreePath !== root + '/.dsh-kanban/worktrees/' + slug[1]) throw new Error('unsafe-execution-linkage')
  const review = await adapter.review(card.branch, card.reviewUrl)
  if (review === null) return { reviewUrl: card.reviewUrl, state: 'missing', merged: false }
  const reviewUrl = card.reviewUrl || review.url
  let text = adapter.setTicketAttr(request.text, 'reviewUrl', reviewUrl)
  if (text === null) throw new Error('not-a-ticket-file')
  if (card.reviewUrl === '') await adapter.persistTicket(text)
  if (!review.merged) return { reviewUrl, state: review.state, merged: false }

  const worktrees = await adapter.git(['worktree', 'list', '--porcelain'])
  const entries = worktrees.text.trim().split(/\r?\n\r?\n/).filter(Boolean).map((block) => block.split(/\r?\n/))
  const assigned = entries.find((lines) => lines.includes('worktree ' + card.worktreePath))
  const expectedBranch = 'branch refs/heads/' + card.branch
  if (assigned && !assigned.includes(expectedBranch)) throw new Error('worktree-branch-mismatch')
  if (entries.some((lines) => lines !== assigned && lines.includes(expectedBranch))) throw new Error('ticket-branch-checked-out-elsewhere')
  if (assigned) {
    const dirty = await adapter.git(['-C', card.worktreePath, 'status', '--porcelain', '--untracked-files=all', '--ignored'])
    if (dirty.text !== '') throw new Error('worktree-not-clean: preserve uncommitted and ignored files first')
  }
  const branch = await adapter.git(['rev-parse', '--verify', 'refs/heads/' + card.branch], [0, 128])
  const branchPresent = branch.exitCode === 0
  const head = branchPresent ? branch.text.trim() : ''
  await adapter.releaseSession()
  if (assigned) await adapter.git(['worktree', 'remove', card.worktreePath])
  if (branchPresent) await adapter.git(['update-ref', '-d', 'refs/heads/' + card.branch, head])
  for (const [key, value] of [['column', 'done'], ['branch', null], ['worktreePath', null], ['sessionId', null]]) {
    text = adapter.setTicketAttr(text, key, value)
  }
  await adapter.persistTicket(text)
  return { reviewUrl, state: 'merged', merged: true }
}

async function kanbanAcceptLocalTicket(request, adapter) {
  const review = await kanbanLocalReview(request, adapter.git)
  const expected = request.review
  if (!expected || ['baseBranch', 'baseSha', 'head', 'branchPresent', 'worktreePresent', 'cleanupPending', 'recordedMergeSha'].some((key) => expected[key] !== review[key])) throw new Error('review-changed: review the current diff before accepting')
  if (!review.canAccept) throw new Error(review.conflict || 'merge-conflict')
  const card = parseTicketFile(request.file, request.text)
  if ((await adapter.git(['symbolic-ref', '--short', 'HEAD'])).text.trim() !== review.baseBranch) throw new Error('base-not-checked-out: switch to ' + review.baseBranch)
  if ((await adapter.git(['status', '--porcelain', '--untracked-files=all', '--', '.', ':(exclude).dsh-kanban', ':(exclude).gitignore'])).text !== '') throw new Error('workspace-not-clean: commit or preserve local changes first')
  if (review.worktreePresent && (await adapter.git(['-C', card.worktreePath, 'status', '--porcelain', '--untracked-files=all', '--ignored'])).text !== '') throw new Error('worktree-not-clean: preserve uncommitted and ignored files first')
  if ((await adapter.git(['rev-parse', 'HEAD'])).text.trim() !== review.baseSha) throw new Error('review-changed: Base Branch changed before merge')
  if (!review.cleanupPending) await adapter.git(['merge', '--ff', '--no-edit', review.head])
  const currentBaseSha = (await adapter.git(['rev-parse', 'HEAD'])).text.trim()
  const mergeSha = review.cleanupPending && card.mergeSha !== '' ? card.mergeSha : currentBaseSha
  let text = kanbanSetAttr(request.text, 'mergeSha', mergeSha)
  await adapter.persistTicket(text)
  await adapter.releaseSession()
  if (review.worktreePresent) await adapter.git(['worktree', 'remove', card.worktreePath])
  if (review.branchPresent) await adapter.git(['update-ref', '-d', 'refs/heads/' + card.branch, review.head])
  for (const [key, value] of [['column', 'done'], ['branch', null], ['worktreePath', null], ['sessionId', null]]) text = kanbanSetAttr(text, key, value)
  await adapter.persistTicket(text)
  return { mergeSha, column: 'done' }
}

async function kanbanLocalReview(request, git) {
  if ((await git(['remote'])).text.trim() !== '') throw new Error('local-completion-only: Workspace has a remote')
  const card = parseTicketFile(request.file, request.text)
  if (!card || card.column !== 'in-review') throw new Error('ticket-not-in-review')
  const slug = /^kan-\d+-([a-z0-9-]+)\.md$/i.exec(request.file)
  if (!slug || card.branch !== 'kanban/' + card.id + '-' + slug[1] ||
      card.worktreePath !== request.workspacePath.replace(/\/+$/, '') + '/.dsh-kanban/worktrees/' + slug[1]) throw new Error('unsafe-execution-linkage')
  const attrs = kanbanParseFrontmatter(request.text).attrs
  const baseBranch = String(attrs.baseBranch || '').trim()
  if (baseBranch === '') throw new Error('base-branch-missing: restart the Ticket to record its Base Branch')
  const baseSha = (await git(['rev-parse', '--verify', 'refs/heads/' + baseBranch])).text.trim()
  const branchResult = await git(['rev-parse', '--verify', 'refs/heads/' + card.branch], [0, 128])
  const branchPresent = branchResult.exitCode === 0
  const head = branchPresent ? branchResult.text.trim() : card.mergeSha
  if (head === '') throw new Error('ticket-branch-not-found')
  const merged = await git(['merge-base', '--is-ancestor', head, baseSha], [0, 1])
  const cleanupPending = merged.exitCode === 0
  const diff = await git(['diff', '--no-ext-diff', '--no-textconv', '--no-color', baseSha + '...' + head, '--'])
  const merge = cleanupPending ? { exitCode: 0, text: '' } : await git(['merge-tree', '--write-tree', baseSha, head], [0, 1])
  const conflict = merge.exitCode === 1 ? merge.text : null
  const worktrees = await git(['worktree', 'list', '--porcelain'])
  const entries = worktrees.text.trim().split(/\r?\n\r?\n/).map((block) => block.split(/\r?\n/))
  const assigned = entries.find((lines) => lines.includes('worktree ' + card.worktreePath))
  const expectedBranch = 'branch refs/heads/' + card.branch
  if (assigned && !assigned.includes(expectedBranch)) throw new Error('worktree-branch-mismatch')
  if (entries.some((lines) => lines !== assigned && lines.includes(expectedBranch))) throw new Error('ticket-branch-checked-out-elsewhere')
  const worktreePresent = assigned !== undefined
  if (!worktreePresent && !cleanupPending) throw new Error('ticket-worktree-not-found')
  return { baseBranch, baseSha, head, branchPresent, worktreePresent, cleanupPending,
    recordedMergeSha: card.mergeSha,
    diff: diff.text, truncated: diff.truncated, conflict,
    canAccept: conflict === null }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    kanbanDetectRemote,
    kanbanProbeRemotePlatform,
    kanbanRemotePlatformAdapter,
    kanbanCompleteRemoteTicket,
    kanbanRemotePollDelay,
    kanbanAcceptLocalTicket,
    kanbanLocalReview,
  }
}

// Remote Issue integration helpers. Concatenate after completion.js and
// before host.js. Plain JavaScript only.

function kanbanIssueImportAdapter(remote, command) {
  if (!remote || (remote.platform !== 'github' && remote.platform !== 'gitlab')) {
    throw new Error('unsupported-remote-platform')
  }
  const parsePage = (text) => {
    let values
    try { values = JSON.parse(String(text || '')) } catch { throw new Error(remote.platform + '-issues-invalid-json') }
    if (!Array.isArray(values)) throw new Error(remote.platform + '-issues-invalid-response')
    return values
  }
  const normalize = remote.platform === 'github'
    ? (values) => values.map((value) => ({
        number: Number(value.number),
        title: String(value.title || ''),
        body: String(value.body || ''),
        url: String(value.url || ''),
      }))
    : (values) => values.map((value) => ({
        number: Number(value.iid),
        title: String(value.title || ''),
        body: String(value.description || ''),
        url: String(value.web_url || ''),
      }))
  return {
    async listOpen() {
      if (remote.platform === 'github') {
        const result = await command([
          'gh', 'issue', 'list', '--repo', remote.repo, '--state', 'open', '--limit', '1000',
          '--json', 'number,title,body,url',
        ])
        return normalize(parsePage(result.text))
      }
      const issues = []
      for (let page = 1;; page += 1) {
        const result = await command([
          'glab', 'issue', 'list', '--repo', remote.url || remote.repo, '--page', String(page),
          '--per-page', '100', '--output', 'json',
        ])
        const values = parsePage(result.text)
        issues.push(...normalize(values))
        if (values.length < 100) return issues
      }
    },
  }
}

// Bind one supported platform CLI to Board-owned Issue label writes.
function kanbanIssueSyncAdapter(remote, command) {
  if (!remote || (remote.platform !== 'github' && remote.platform !== 'gitlab')) {
    throw new Error('unsupported-remote-platform')
  }
  const issueNumber = (issueUrl) => {
    const pattern = remote.platform === 'github' ? /\/issues\/(\d+)(?:[/?#]|$)/ : /\/-\/issues\/(\d+)(?:[/?#]|$)/
    const match = pattern.exec(String(issueUrl || ''))
    if (match === null) throw new Error(remote.platform + '-issue-url-invalid')
    return match[1]
  }
  const labelNames = (values) => values.map((label) =>
    String(typeof label === 'string' ? label : label && label.name || '')).filter((label) => label !== '')
  const parseJson = (text, kind) => {
    try { return JSON.parse(String(text || '')) } catch { throw new Error(remote.platform + '-' + kind + '-invalid-json') }
  }
  const ensureLabel = async (target) => {
    if (remote.platform === 'github') {
      const values = parseJson((await command([
        'gh', 'label', 'list', '--repo', remote.repo, '--search', target, '--limit', '100', '--json', 'name',
      ])).text, 'labels')
      if (!Array.isArray(values)) throw new Error('github-labels-invalid-response')
      if (!labelNames(values).includes(target)) await command(['gh', 'label', 'create', target, '--repo', remote.repo])
      return
    }
    for (let page = 1;; page += 1) {
      const values = parseJson((await command([
        'glab', 'label', 'list', '--repo', remote.repo, '--output', 'json',
        '--page', String(page), '--per-page', '100',
      ])).text, 'labels')
      if (!Array.isArray(values)) throw new Error('gitlab-labels-invalid-response')
      if (labelNames(values).includes(target)) return
      if (values.length < 100) {
        await command(['glab', 'label', 'create', '--name', target, '--repo', remote.repo])
        return
      }
    }
  }
  const project = remote.repo.split('/').slice(1).join('/')
  const normalizeState = (state) => {
    const value = String(state || '').toLowerCase()
    return value === 'opened' ? 'open' : value
  }
  const normalizeComment = (comment) => ({
    id: String(comment && comment.id || ''),
    author: String(comment && comment.author && (comment.author.login || comment.author.username) || ''),
    body: String(comment && comment.body || ''),
    url: String(comment && (comment.url || comment.web_url) || ''),
    createdAt: String(comment && (comment.createdAt || comment.created_at) || ''),
  })
  const normalizeBlocker = (issue) => ({
    id: String(issue && issue.id || ''),
    number: Number(issue && (issue.number || issue.iid)),
    title: String(issue && issue.title || ''),
    url: String(issue && (issue.url || issue.web_url) || ''),
    state: normalizeState(issue && issue.state),
  })
  return {
    async read(issueUrl) {
      const number = issueNumber(issueUrl)
      if (remote.platform === 'github') {
        const issue = parseJson((await command([
          'gh', 'issue', 'view', issueUrl, '--repo', remote.repo,
          '--json', 'title,body,state,comments,labels,blockedBy',
        ])).text, 'issue')
        if (!issue || !Array.isArray(issue.comments) || !Array.isArray(issue.labels) ||
            !issue.blockedBy || !Array.isArray(issue.blockedBy.nodes)) {
          throw new Error('github-issue-invalid-response')
        }
        return {
          title: String(issue.title || ''),
          body: String(issue.body || ''),
          state: normalizeState(issue.state),
          labels: labelNames(issue.labels),
          comments: issue.comments.map(normalizeComment),
          blockers: issue.blockedBy.nodes.map(normalizeBlocker),
        }
      }
      const root = 'projects/' + encodeURIComponent(project) + '/issues/' + number
      const issue = parseJson((await command(['glab', 'api', root])).text, 'issue')
      const notes = parseJson((await command(['glab', 'api', root + '/notes', '--paginate'])).text, 'issue-comments')
      const links = parseJson((await command(['glab', 'api', root + '/links', '--paginate'])).text, 'issue-links')
      if (!issue || !Array.isArray(issue.labels) || !Array.isArray(notes) || !Array.isArray(links)) {
        throw new Error('gitlab-issue-invalid-response')
      }
      return {
        title: String(issue.title || ''),
        body: String(issue.description || ''),
        state: normalizeState(issue.state),
        labels: labelNames(issue.labels),
        comments: notes.filter((note) => note && note.system !== true).map(normalizeComment),
        blockers: links.filter((link) => link && link.link_type === 'is_blocked_by').map(normalizeBlocker),
      }
    },
    async setColumn(issueUrl, column) {
      const target = 'kanban:' + String(column || '')
      const number = issueNumber(issueUrl)
      await ensureLabel(target)
      const viewArgs = remote.platform === 'github'
        ? ['gh', 'issue', 'view', issueUrl, '--repo', remote.repo, '--json', 'labels,state']
        : ['glab', 'issue', 'view', number, '--repo', remote.repo, '--output', 'json']
      const issue = parseJson((await command(viewArgs)).text, 'issue')
      if (!issue || !Array.isArray(issue.labels)) throw new Error(remote.platform + '-issue-invalid-response')
      const labels = labelNames(issue.labels)
      const stale = labels.filter((label) => label.startsWith('kanban:') && label !== target)
      const hasTarget = labels.includes(target)
      if (!hasTarget || stale.length > 0) {
        const editArgs = remote.platform === 'github'
          ? ['gh', 'issue', 'edit', issueUrl, '--repo', remote.repo]
          : ['glab', 'issue', 'update', number, '--repo', remote.repo]
        if (!hasTarget) editArgs.push(remote.platform === 'github' ? '--add-label' : '--label', target)
        if (stale.length > 0) {
          editArgs.push(remote.platform === 'github' ? '--remove-label' : '--unlabel', stale.join(','))
        }
        await command(editArgs)
      }
      if (column !== 'done' && normalizeState(issue.state) === 'closed') {
        await command(remote.platform === 'github'
          ? ['gh', 'issue', 'reopen', issueUrl, '--repo', remote.repo]
          : ['glab', 'issue', 'reopen', number, '--repo', remote.repo])
      }
    },
    async complete(issueUrl, reviewUrl) {
      const number = issueNumber(issueUrl)
      const reference = String(reviewUrl || '').trim()
      if (reference === '') throw new Error('completion-review-url-required')
      const marker = '<!-- dsh-kanban-completion:' + reference + ' -->'
      const message = 'Completed by merged PR/MR: ' + reference + '\n\n' + marker
      if (remote.platform === 'github') {
        const value = parseJson((await command([
          'gh', 'issue', 'view', issueUrl, '--repo', remote.repo, '--json', 'state,comments',
        ])).text, 'issue')
        if (!value || !Array.isArray(value.comments)) throw new Error('github-issue-invalid-response')
        const hasComment = value.comments.some((comment) => String(comment && comment.body || '').includes(marker))
        const open = String(value.state || '').toLowerCase() !== 'closed'
        if (!hasComment && open) {
          await command(['gh', 'issue', 'close', issueUrl, '--repo', remote.repo, '--comment', message])
          return
        }
        if (!hasComment) await command(['gh', 'issue', 'comment', issueUrl, '--repo', remote.repo, '--body', message])
        if (open) await command(['gh', 'issue', 'close', issueUrl, '--repo', remote.repo])
        return
      }
      const issue = parseJson((await command([
        'glab', 'issue', 'view', number, '--repo', remote.repo, '--output', 'json',
      ])).text, 'issue')
      const notes = parseJson((await command([
        'glab', 'api', 'projects/' + encodeURIComponent(project) + '/issues/' + number + '/notes', '--paginate',
      ])).text, 'issue-comments')
      if (!Array.isArray(notes)) throw new Error('gitlab-issue-comments-invalid-response')
      if (!notes.some((note) => String(note && note.body || '').includes(marker))) {
        await command(['glab', 'issue', 'note', number, '--repo', remote.repo, '--message', message])
      }
      if (String(issue && issue.state || '').toLowerCase() !== 'closed') {
        await command(['glab', 'issue', 'close', number, '--repo', remote.repo])
      }
    },
  }
}

const kanbanIssueSyncRecordSchema = {
  parse(value) {
    if (value === null || typeof value !== 'object' || Array.isArray(value)) {
      throw new Error('Issue sync record must be an object')
    }
    const comments = Array.isArray(value.comments) ? value.comments : []
    const blockers = Array.isArray(value.blockers) ? value.blockers : []
    if (typeof value.issue !== 'string' || typeof value.error !== 'string' ||
        typeof value.lastAttemptAt !== 'string' || typeof value.lastSuccessAt !== 'string' ||
        comments.some((entry) => !entry || typeof entry.body !== 'string') ||
        blockers.some((entry) => !entry || typeof entry.title !== 'string' || typeof entry.state !== 'string')) {
      throw new Error('Issue sync record is malformed')
    }
    return {
      issue: value.issue,
      comments: comments.map((entry) => ({
        id: String(entry.id || ''), author: String(entry.author || ''), body: entry.body,
        url: String(entry.url || ''), createdAt: String(entry.createdAt || ''),
      })),
      blockers: blockers.map((entry) => ({
        id: String(entry.id || ''), number: Number(entry.number), title: entry.title,
        url: String(entry.url || ''), state: entry.state,
      })),
      error: value.error,
      lastAttemptAt: value.lastAttemptAt,
      lastSuccessAt: value.lastSuccessAt,
    }
  },
}

function kanbanIssueLinkKey(value) {
  return String(value || '').trim().replace(/[?#].*$/, '').replace(/\/+$/, '')
}

function kanbanMarkImportedIssues(issues, tickets) {
  const linked = new Set((tickets || []).map((ticket) => kanbanIssueLinkKey(ticket.issue)).filter(Boolean))
  return (issues || []).map((issue) => ({
    ...issue,
    imported: linked.has(kanbanIssueLinkKey(issue.url)),
  }))
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { kanbanIssueImportAdapter, kanbanIssueSyncAdapter, kanbanIssueLinkKey, kanbanMarkImportedIssues }
}

// Host half of the kanban Plugin — execution, review Bounce, and Stalled recovery.
//
// `cordis_define` receives plugin/frontmatter.js, plugin/settings.js,
// plugin/queue.js, plugin/execution.js, plugin/watch.js, plugin/bounce.js, and
// plugin/completion.js and plugin/import.js concatenate before this file. Their helpers are in scope. Plain JavaScript only: no
// imports, no TypeScript, and no Node globals.
//
// Write behaviour: every Ticket File write goes through the fs service's
// writeText, which stages the content in a private temp file and publishes
// it with rename — that is the "temp file + rename" atomicity issue #2 asks
// for, provided by the service and not re-implemented here. ticket.create
// additionally passes { kind: 'createIfAbsent' } so a racing creator's file
// is never overwritten.

return {
  inject: ['workspaceRegistry', 'fs', 'storageDomain', 'shell', 'agents', 'agentDefaultModel', 'agentPresets', 'skills'],
  async apply(ctx) {
    const registry = ctx.workspaceRegistry
    const fs = ctx.fs
    const storageDomain = ctx.storageDomain
    const shell = ctx.shell
    const agents = ctx.agents
    const agentDefaultModel = ctx.agentDefaultModel
    const agentPresets = ctx.agentPresets
    const skills = ctx.skills
    // Retain exact factory handles: disposing an Agent scope alone does not
    // unregister its session. Never dispose an unrelated, externally owned Agent.
    const sessionHandles = new Map()
    const rememberSession = (handle) => sessionHandles.set(handle.agent.id, handle)

    const settingsDomain = await storageDomain.open({
      name: 'kanban_settings',
      version: 1,
      tables: { workspaces: { valueSchema: kanbanSettingsRecordSchema } },
    })
    const settingsTable = settingsDomain.table('workspaces')
    const executionDomain = await storageDomain.open({
      name: 'kanban_execution',
      version: 1,
      tables: { tickets: { valueSchema: kanbanExecutionRecordSchema } },
    })
    const executionTable = executionDomain.table('tickets')
    const issueSyncDomain = await storageDomain.open({
      name: 'kanban_issue_sync',
      version: 1,
      tables: { tickets: { valueSchema: kanbanIssueSyncRecordSchema } },
    })
    const issueSyncTable = issueSyncDomain.table('tickets')
    let settingsAdmissionOpen = true
    let settingsTail = Promise.resolve()

    const enqueueSettings = (operation) => {
      if (!settingsAdmissionOpen) return Promise.reject(new Error('Board settings are stopping'))
      const result = settingsTail.then(operation)
      settingsTail = result.then(
        () => undefined,
        () => undefined,
      )
      return result
    }

    let moveAdmissionOpen = true
    let moveTail = Promise.resolve()

    // Ticket moves mutate shared WIP queue state. One tail serializes every
    // ticket.move, so two overlapping drops cannot both win the last slot.
    // Moves are human-paced, so waiting behind an auto-spawn is acceptable.
    const enqueueMove = (operation) => {
      if (!moveAdmissionOpen) return Promise.reject(new Error('Board ticket moves are stopping'))
      const result = moveTail.then(operation)
      moveTail = result.then(
        () => undefined,
        () => undefined,
      )
      return result
    }

    ctx.effect(
      () => async () => {
        settingsAdmissionOpen = false
        moveAdmissionOpen = false
        await settingsTail
        await moveTail
        if (issueSweepRunning !== undefined) await issueSweepRunning
        await issueSyncDomain.close()
        await executionDomain.close()
        await settingsDomain.close()
      },
      'kanban.settingsDomainClose',
    )

    const settingsView = (workspace, settings) => ({
      workspaceId: String(workspace.id),
      title: workspace.title,
      path: settings.path,
      wipLimit: settings.wipLimit,
      autopilot: settings.autopilot,
    })

    const persistWorkspaceSettings = async (workspaceId, settings) => {
      const current = settingsTable.get(workspaceId)
      if (
        current === undefined ||
        current.path !== settings.path ||
        current.wipLimit !== settings.wipLimit ||
        current.autopilot !== settings.autopilot
      ) {
        await settingsTable.put(workspaceId, settings)
      }
      return settings
    }

    const ensureWorkspaceSettings = async (workspace) => {
      const entry = kanbanWorkspaceSettingEntries(
        [workspace],
        (workspaceId) => settingsTable.get(workspaceId),
      )[0]
      return persistWorkspaceSettings(entry.workspaceId, entry.settings)
    }

    const syncWorkspaceSettings = async () => {
      const workspaces = registry.list()
      const entries = kanbanWorkspaceSettingEntries(
        workspaces,
        (workspaceId) => settingsTable.get(workspaceId),
      )
      const liveIds = new Set(entries.map((entry) => entry.workspaceId))
      const result = []
      for (let index = 0; index < entries.length; index += 1) {
        const entry = entries[index]
        const settings = await persistWorkspaceSettings(entry.workspaceId, entry.settings)
        result.push(settingsView(workspaces[index], settings))
      }
      for (const workspaceId of settingsTable.keys()) {
        if (!liveIds.has(String(workspaceId))) await settingsTable.delete(workspaceId)
      }
      return result
    }

    ctx.on('domain/changed', (change) => {
      if (change.domain !== 'workspace' || change.table !== 'workspaces' || !settingsAdmissionOpen) return
      void enqueueSettings(syncWorkspaceSettings).catch((err) => {
        console.error('kanban settings sync failed: ' + String((err && err.message) || err))
      })
    })

    // Materialize the UUID-to-path mapping for every registered Workspace.
    await enqueueSettings(syncWorkspaceSettings)

    // Only real Ticket File names are ever resolved for read/write; this
    // stops path traversal through crafted `file` arguments.
    const isTicketFileName = (file) => /^kan-\d+-[a-z0-9-]+\.md$/i.test(file)

    const workspaceOf = (args) => {
      const workspaceId = args && typeof args.workspaceId === 'string' ? args.workspaceId : ''
      if (workspaceId === '') return { error: 'workspaceId required' }
      const workspace = registry.get(workspaceId)
      if (workspace === undefined) return { error: 'workspace-not-found' }
      return { workspaceId, workspace }
    }

    const ticketsDir = (workspace) => workspace.path.replace(/\/+$/, '') + '/.dsh-kanban/tickets'

    // Load one existing Ticket File for the update/move methods.
    const readTicket = async (dirPath, file) => {
      if (!isTicketFileName(file)) return { error: 'invalid-ticket-file' }
      const target = await fs.resolve(dirPath + '/' + file)
      const info = await fs.stat(target)
      if (info === undefined || info.type !== 'file') return { error: 'ticket-not-found' }
      const text = await fs.readText(target)
      if (parseTicketFile(file, text) === null) return { error: 'not-a-ticket-file' }
      return { target, text }
    }

    const syncExecutionLinkage = async (workspaceId, card) => {
      const key = workspaceId + '/' + card.id
      const stored = executionTable.get(key)
      if (card.sessionId === '' || card.worktreePath === '' || card.branch === '') {
        if (stored !== undefined) await executionTable.delete(key)
        return
      }
      const linkage = {
        workspaceId,
        ticketId: card.id,
        sessionId: card.sessionId,
        worktreePath: card.worktreePath,
        branch: card.branch,
        // The spawn sha is recorded by ticket execution and cannot be
        // derived from the Ticket File; carry it across re-syncs so the
        // watch loop's commit check survives a linkage rewrite.
        baseSha: stored !== undefined && typeof stored.baseSha === 'string' ? stored.baseSha : '',
      }
      if (
        stored === undefined ||
        stored.sessionId !== linkage.sessionId ||
        stored.worktreePath !== linkage.worktreePath ||
        stored.branch !== linkage.branch
      ) {
        await executionTable.put(key, linkage)
      }
    }

    // The durable WIP limit for one Workspace as stored right now; moves and
    // the queue pump read it without repairing the settings record.
    const workspaceSettingsFor = (workspaceLookup) =>
      kanbanWorkspaceSettings(workspaceLookup.workspace, settingsTable.get(workspaceLookup.workspaceId))

    const wipLimitFor = (workspaceLookup) => workspaceSettingsFor(workspaceLookup).wipLimit
    const autopilotFor = (workspaceLookup) => workspaceSettingsFor(workspaceLookup).autopilot

    // Scan a Workspace's Ticket Files into card data, repairing each card's
    // derived execution linkage while reading. A missing directory is an
    // empty Board, not an error; a single unreadable file is logged and
    // skipped. Shared by board.list, queue admission, and the queue pump.
    const readBoardCards = async (workspaceLookup) => {
      const dir = await fs.resolve(ticketsDir(workspaceLookup.workspace))
      const info = await fs.stat(dir)
      if (info === undefined || info.type !== 'directory') return []
      const entries = await fs.listDir(dir)
      const tickets = []
      for (const entry of entries) {
        if (entry.type !== 'file' || !entry.name.toLowerCase().endsWith('.md')) continue
        try {
          const text = await fs.readText(entry.target)
          const card = parseTicketFile(entry.name, text)
          if (card !== null) {
            try {
              await syncExecutionLinkage(workspaceLookup.workspaceId, card)
            } catch (err) {
              console.error('kanban: execution linkage sync failed for ' + card.id + ': ' + String((err && err.message) || err))
            }
            tickets.push({ ...card, file: entry.name })
          }
        } catch (err) {
          console.error('kanban: skipping unreadable Ticket File ' + entry.name + ': ' + String((err && err.message) || err))
        }
      }
      return tickets
    }

    // pumpQueue auto-spawns queued Tickets while slots are free: the earliest
    // queued Ticket per free slot, re-reading the Board after each spawn. It
    // runs after any move that can free a slot or grow the queue. A failed
    // spawn leaves the Ticket queued (kanbanStartTicketExecution rolls back)
    // and the next move retries, so callers only log pump failures.
    const pumpQueue = async (workspaceLookup) => {
      const dirPath = ticketsDir(workspaceLookup.workspace)
      for (;;) {
        const tickets = await readBoardCards(workspaceLookup)
        const plan = kanbanQueuePlan({ tickets, wipLimit: wipLimitFor(workspaceLookup) })
        if (plan === undefined) return
        const slugMatch = /^kan-\d+-([a-z0-9-]+)\.md$/i.exec(plan.file)
        if (slugMatch === null) return
        const loaded = await readTicket(dirPath, plan.file)
        if (loaded.error !== undefined) return
        const card = parseTicketFile(plan.file, loaded.text)
        if (card === null || !kanbanIsQueued(card)) return
        if (card.issue !== '') {
          const syncRecord = await refreshIssueProjection(workspaceLookup, card, false)
          const blockers = syncRecord === undefined
            ? [] : syncRecord.blockers.filter((blocker) => blocker.state === 'open')
          if (blockers.length > 0) {
            let text = kanbanSetAttr(loaded.text, 'column', 'ready')
            text = kanbanSetAttr(text, 'queued', null)
            if (text === null) return
            await fs.writeText(loaded.target, text)
            await syncIssueColumn(workspaceLookup, card, 'ready')
            continue
          }
          await syncIssueColumn(workspaceLookup, card, 'in-progress')
        }
        await kanbanStartTicketExecution(
          {
            workspaceId: workspaceLookup.workspaceId,
            workspacePath: workspaceLookup.workspace.path,
            ticketId: card.id,
            ticketSlug: slugMatch[1],
            ticketText: loaded.text,
            issueUrl: card.issue,
            baseMode: card.base,
            autopilot: autopilotFor(workspaceLookup),
          },
          kanbanHostExecutionAdapter({
            workspace: workspaceLookup.workspace,
            loaded,
            fs,
            shell,
            agents,
            rememberSession,
            agentDefaultModel,
            agentPresets,
            executionTable,
            setTicketAttr: kanbanSetAttr,
          }),
        )
      }
    }

    const logPumpFailure = (err) => {
      console.error('kanban: queue pump failed, queued Tickets keep their state: ' + String((err && err.message) || err))
    }

    // moveTicket runs serialized behind enqueueMove. Ready → In Progress is
    // the only move that spawns execution (ADR-0001), so it is also the only
    // move the WIP queue gates: past the limit, or when queued Tickets
    // already wait, the Ticket queues instead of spawning. Every other move
    // stays the surgical column write; a Ticket leaving In Progress drops
    // its queue marker, so dragging a queued Ticket to Ready dequeues it
    // with no session spawned. After any move that can free a slot, the
    // pump auto-spawns the earliest queued Ticket.
    const moveTicket = async (workspaceLookup, file, column) => {
      const dirPath = ticketsDir(workspaceLookup.workspace)
      const loaded = await readTicket(dirPath, file)
      if (loaded.error !== undefined) return { ok: false, error: loaded.error }
      const card = parseTicketFile(file, loaded.text)
      if (card === null) return { ok: false, error: 'not-a-ticket-file' }

      if (card.column === 'in-progress' && !kanbanIsQueued(card) && column === 'ready') {
        return { ok: false, error: 'send-back-required' }
      }

      if (card.column === 'in-review' && column !== 'in-review') {
        if (column === 'done') return { ok: false, error: 'accept-required' }
        if (column === 'in-progress') return { ok: false, error: 'bounce-comment-required' }
        return { ok: false, error: 'review-decision-required' }
      }
      if (column === 'done' && card.column !== 'done') return { ok: false, error: 'completion-required' }

      // A queued Ticket dropped on In Progress again is already in line.
      if (column === 'in-progress' && kanbanIsQueued(card)) {
        return { ok: true, file, column, queued: true }
      }

      if (column === 'in-progress' && card.column === 'ready') {
        if (card.issue !== '') await refreshIssueProjection(workspaceLookup, card)
        const syncRecord = issueSyncTable.get(workspaceLookup.workspaceId + '/' + card.id)
        const blockers = syncRecord === undefined
          ? [] : syncRecord.blockers.filter((blocker) => blocker.state === 'open')
        if (blockers.length > 0) return { ok: false, error: 'issue-blocked', blockers }
        if (card.sessionId !== '') return { ok: false, error: 'ticket-already-started' }
        const tickets = await readBoardCards(workspaceLookup)
        const admission = kanbanQueueAdmission({ tickets, wipLimit: wipLimitFor(workspaceLookup) })
        if (admission.action === 'queue') {
          let queuedText = kanbanSetAttr(loaded.text, 'column', column)
          queuedText = kanbanSetAttr(queuedText, 'queued', new Date().toISOString())
          if (queuedText === null) return { ok: false, error: 'not-a-ticket-file' }
          await fs.writeText(loaded.target, queuedText)
          await syncIssueColumn(workspaceLookup, card, column)
          // The queue head may now have a free slot (issue #5 keeps the
          // queue strictly FIFO — the moved Ticket never jumps it).
          await pumpQueue(workspaceLookup).catch(logPumpFailure)
          return { ok: true, file, column, queued: true }
        }
        const slugMatch = /^kan-\d+-([a-z0-9-]+)\.md$/i.exec(file)
        if (slugMatch === null) return { ok: false, error: 'invalid-ticket-file' }
        const linkage = await kanbanStartTicketExecution(
          {
            workspaceId: workspaceLookup.workspaceId,
            workspacePath: workspaceLookup.workspace.path,
            ticketId: card.id,
            ticketSlug: slugMatch[1],
            ticketText: loaded.text,
            issueUrl: card.issue,
            baseMode: card.base,
            autopilot: autopilotFor(workspaceLookup),
          },
          kanbanHostExecutionAdapter({
            workspace: workspaceLookup.workspace,
            loaded,
            fs,
            shell,
            agents,
            rememberSession,
            agentDefaultModel,
            agentPresets,
            executionTable,
            setTicketAttr: kanbanSetAttr,
          }),
        )
        await syncIssueColumn(workspaceLookup, card, column)
        return { ok: true, file, column, ...linkage }
      }

      let text = kanbanSetAttr(loaded.text, 'column', column)
      if (kanbanIsQueued(card)) text = kanbanSetAttr(text, 'queued', null)
      if (text === null) return { ok: false, error: 'not-a-ticket-file' }
      await fs.writeText(loaded.target, text)
      await syncIssueColumn(workspaceLookup, card, column)
      await pumpQueue(workspaceLookup).catch(logPumpFailure)
      return { ok: true, file, column }
    }

    // Session-watch state (issue #6). Both maps are live-only: they are
    // rebuilt from real events as sessions run, and the durable facts stay
    // in the Ticket Files and the execution linkage table.
    const watchAttention = new Map() // sessionId → 'approval' | 'error' | 'finished'
    const watchMessages = new Map() // sessionId → owned error message
    const watchLastTurnEnd = new Map() // sessionId → last turn/end reason kind
    const watchRevision = new Map() // sessionId → generation of the current turn
    const invalidateWatch = (sessionId) => {
      watchRevision.set(sessionId, (watchRevision.get(sessionId) || 0) + 1)
      watchLastTurnEnd.delete(sessionId)
      watchAttention.delete(sessionId)
      watchMessages.delete(sessionId)
    }

    const cardAttention = (card) => {
      const attention = watchAttention.get(card.sessionId) || null
      if (card.column !== 'in-progress' || kanbanIsQueued(card)) return attention
      const agent = agents.get(card.sessionId)
      if (!card.sessionId || agent === undefined) return 'error'
      if (agent.status === 'idle' && attention !== 'approval') return 'error'
      return attention
    }

    const cardIssueSync = (workspaceId, card) => {
      if (card.issue === '') return { issueComments: [], issueBlockers: [], sync: null }
      const record = issueSyncTable.get(String(workspaceId) + '/' + card.id)
      if (record === undefined) {
        return { issueComments: [], issueBlockers: [], sync: { status: 'pending', error: '', lastSuccessAt: '' } }
      }
      return {
        issueComments: record.comments,
        issueBlockers: record.blockers.filter((blocker) => blocker.state === 'open'),
        sync: {
          status: record.error === '' ? 'ok' : 'error',
          error: record.error,
          lastSuccessAt: record.lastSuccessAt,
        },
      }
    }

    // Locate one Ticket File by its Ticket id. The Ticket File — not the
    // linkage record — is the source of truth for the Ticket's column.
    const findTicketByTicketId = async (workspaceId, ticketId) => {
      const workspace = registry.get(workspaceId)
      if (workspace === undefined) return undefined
      let dir
      try {
        dir = await fs.resolve(ticketsDir(workspace))
        const info = await fs.stat(dir)
        if (info === undefined || info.type !== 'directory') return undefined
      } catch {
        return undefined
      }
      const entries = await fs.listDir(dir)
      for (const entry of entries) {
        if (entry.type !== 'file' || !entry.name.toLowerCase().endsWith('.md')) continue
        try {
          const text = await fs.readText(entry.target)
          const card = parseTicketFile(entry.name, text)
          if (card !== null && card.id === ticketId) return { card, text, target: entry.target, file: entry.name }
        } catch {
          // An unreadable Ticket File cannot be watched; skip it.
        }
      }
      return undefined
    }

    const watchRunGit = async (workdir, args) => {
      const result = await kanbanRunHostGit(shell, workdir, args, { stdoutMaxBytes: 65536 })
      return result.text.trim()
    }

    // Bind the dynamic Host capabilities to the Board session-watch seam
    // (plugin/watch.js). Every side effect goes through this adapter.
    const watchAdapter = {
      async linkageFor(sessionId) {
        for (const key of executionTable.keys()) {
          const linkage = executionTable.get(key)
          if (linkage !== undefined && linkage.sessionId === sessionId) return linkage
        }
        return undefined
      },
      async linkedTicketColumn(linkage) {
        const found = await findTicketByTicketId(linkage.workspaceId, linkage.ticketId)
        // A stale linkage (frontmatter edited by hand) must not move a
        // Ticket that no longer belongs to this session.
        if (found === undefined || found.card.sessionId !== linkage.sessionId) return ''
        return found.card.column
      },
      branchHasCommits: (linkage) => {
        const workspace = registry.get(linkage.workspaceId)
        if (workspace === undefined) return Promise.resolve(false)
        return kanbanBranchHasCommits(linkage, (args) => watchRunGit(workspace.path, args))
      },
      async moveTicketToInReview(linkage, revision) {
        // Recheck inside the move tail: a Bounce or a new turn may have
        // invalidated this completion while the branch check was pending.
        return enqueueMove(async () => {
          const found = await findTicketByTicketId(linkage.workspaceId, linkage.ticketId)
          const workspace = registry.get(linkage.workspaceId)
          if (found === undefined || workspace === undefined ||
            found.card.column !== 'in-progress' || found.card.sessionId !== linkage.sessionId ||
            (watchRevision.get(linkage.sessionId) || 0) !== revision) return false
          const result = await moveTicket(
            { workspaceId: linkage.workspaceId, workspace }, found.file, 'in-review',
          )
          return result.ok
        })
      },
    }

    // Drive one signal through the watch seam. A watch failure must never
    // break the Host event loop, so everything is contained here.
    const forwardWatchSignal = async (request) => {
      const revision = watchRevision.get(request.sessionId) || 0
      try {
        const { attention } = await kanbanHandleSessionSignal(request, {
          ...watchAdapter,
          moveTicketToInReview: (linkage) => watchAdapter.moveTicketToInReview(linkage, revision),
        })
        if (attention !== undefined && (watchRevision.get(request.sessionId) || 0) === revision) {
          if (attention === null) watchAttention.delete(request.sessionId)
          else watchAttention.set(request.sessionId, attention)
        }
      } catch (err) {
        console.error('kanban watch: ' + request.signal + ' for ' + request.sessionId + ' failed: ' + String((err && err.message) || err))
      }
    }

    // The session-watch interface: DSH session events in, watch signals out.
    // `approval/asked` and `approval/decided` are log-only audit events on
    // the session log, so observing them never joins the approval waterfall.
    ctx.on('session/event', (session, event) => {
      const sessionId = session && session.id
      if (sessionId === undefined || sessionId === '') return
      if (event.type === 'turn/end') {
        const kind = (event.data && event.data.reason && event.data.reason.kind) || ''
        const failure = event.data && event.data.reason && event.data.reason.error
        if (kind === 'error') watchMessages.set(sessionId,
          failure && typeof failure.message === 'string' ? failure.message : 'Agent Session errored.')
        watchLastTurnEnd.set(sessionId, kind)
        void forwardWatchSignal({ signal: 'turn-end', sessionId, reason: { kind } })
        return
      }
      if (event.type === 'approval/asked') {
        void forwardWatchSignal({ signal: 'approval-asked', sessionId })
      } else if (event.type === 'approval/decided') {
        void forwardWatchSignal({ signal: 'approval-decided', sessionId })
      }
    })

    // agent/status fires exactly on running ↔ idle transitions; `reasonKind`
    // carries the preceding turn's end reason so an idle after a completed
    // turn can auto-move its Ticket. Any queued input re-opens a turn first,
    // so idle genuinely means the loop is done.
    ctx.on('agent/status', ({ agent, status }) => {
      const sessionId = agent && agent.id
      if (sessionId === undefined || sessionId === '') return
      const reasonKind = status === 'idle' ? watchLastTurnEnd.get(sessionId) : undefined
      if (status === 'running') invalidateWatch(sessionId)
      if (status === 'idle') watchLastTurnEnd.delete(sessionId)
      void forwardWatchSignal({ signal: 'status', sessionId, status, reasonKind })
    })

    ctx.on('agent/error', ({ agent, error }) => {
      const sessionId = agent && agent.id
      if (sessionId === undefined || sessionId === '') return
      invalidateWatch(sessionId)
      watchLastTurnEnd.set(sessionId, 'error')
      watchMessages.set(sessionId, error && typeof error.message === 'string' ? error.message :
        typeof error === 'string' ? error : 'Agent Session errored.')
      void forwardWatchSignal({ signal: 'agent-error', sessionId })
    })

    // board.list({ workspaceId }) → card data for every Ticket File in the
    // Workspace. Ticket Files stay read-only. A missing directory is an
    // empty Board, not an error; a single unreadable file is logged and
    // skipped. Cards carry the full body now: the card editor pre-fills from
    // board.list output, which saves a second round trip per opened Ticket.
    ctx.effect(() =>
      harness.handle('board.list', async (args) => {
        const workspaceLookup = workspaceOf(args)
        if (workspaceLookup.workspace === undefined) return { ok: false, error: workspaceLookup.error }
        try {
          const boardSettings = await enqueueSettings(() => ensureWorkspaceSettings(workspaceLookup.workspace))
          // readBoardCards owns the scan; this view adds each card's live
          // Attention Badge state (issue #6): null when the session needs
          // nothing.
          const tickets = (await readBoardCards(workspaceLookup)).map((card) => ({
            ...card,
            ...cardIssueSync(workspaceLookup.workspaceId, card),
            attention: cardAttention(card),
            stalled: card.column === 'in-progress' && cardAttention(card) === 'error',
            attentionMessage: cardAttention(card) === 'error'
              ? watchMessages.get(card.sessionId) || 'Agent Session stopped before completing the Ticket.' : null,
          }))
          return {
            ok: true,
            workspaceId: workspaceLookup.workspaceId,
            workspaceTitle: workspaceLookup.workspace.title,
            wipLimit: boardSettings.wipLimit,
            autopilot: boardSettings.autopilot,
            tickets,
          }
        } catch (err) {
          return { ok: false, error: 'board-read-failed: ' + String((err && err.message) || err) }
        }
      }),
    )

    const completionGit = (workspace) => (args, allowed = [0]) =>
      kanbanRunHostGit(shell, workspace.path, args, { allowedExitCodes: allowed })
    const remotePollState = new Map()
    let remoteSweepRunning
    const pollRemoteTickets = () => {
      if (remoteSweepRunning !== undefined) return remoteSweepRunning
      remoteSweepRunning = (async () => {
        const now = Date.now()
        for (const workspace of registry.list()) {
          const workspaceId = String(workspace.id)
          const lookup = { workspaceId, workspace }
          const command = (args, allowed = [0]) => kanbanRunHostCommand(shell, workspace.path, args, {
            allowedExitCodes: allowed, timeoutMs: 30000, stdoutMaxBytes: 262144,
          })
          let remote
          try {
            remote = await kanbanDetectRemote(
              completionGit(workspace),
              (location) => kanbanProbeRemotePlatform(location, command),
            )
          } catch (err) {
            console.error('kanban remote detection failed: ' + String((err && err.message) || err))
            continue
          }
          if (remote.platform === 'none') continue
          const platform = kanbanRemotePlatformAdapter(remote, command)
          for (const card of await readBoardCards(lookup)) {
            if (card.column !== 'in-review' || card.branch === '' || card.worktreePath === '') continue
            const key = workspaceId + '/' + card.id + '/' + card.sessionId + '/' + card.branch
            const state = remotePollState.get(key) || { attempt: 0, nextAt: 0 }
            if (state.nextAt > now) continue
            try {
              const result = await enqueueMove(async () => {
                const loaded = await readTicket(ticketsDir(workspace), card.file)
                if (loaded.error !== undefined) throw new Error(loaded.error)
                const current = parseTicketFile(card.file, loaded.text)
                if (!current || current.column !== 'in-review' || current.branch !== card.branch ||
                    current.sessionId !== card.sessionId) return { stale: true }
                const agent = agents.get(current.sessionId)
                if (agent !== undefined && agent.status !== 'idle') throw new Error('session-not-idle')
                const handle = sessionHandles.get(current.sessionId)
                if (agent !== undefined && (!handle || handle.agent !== agent)) throw new Error('session-not-owned-by-board')
                const completed = await kanbanCompleteRemoteTicket({
                  file: card.file, text: loaded.text, workspacePath: workspace.path,
                }, {
                  parseTicketFile,
                  setTicketAttr: kanbanSetAttr,
                  review: (branch, recordedUrl) => platform.review(branch, recordedUrl),
                  git: completionGit(workspace),
                  persistTicket: (text) => fs.writeText(loaded.target, text),
                  async releaseSession() {
                    if (!handle) return
                    await handle.dispose()
                    sessionHandles.delete(current.sessionId)
                  },
                })
                if (completed.merged) {
                  if (current.issue !== '') {
                    const issueSync = kanbanIssueSyncAdapter(remote, command)
                    await issueSync.setColumn(current.issue, 'done')
                    await issueSync.complete(current.issue, completed.reviewUrl)
                  }
                  await executionTable.delete(workspaceId + '/' + current.id)
                  invalidateWatch(current.sessionId)
                  await pumpQueue(lookup).catch(logPumpFailure)
                }
                return completed
              })
              if (result.merged || result.stale) remotePollState.delete(key)
              else remotePollState.set(key, { attempt: state.attempt + 1, nextAt: now + kanbanRemotePollDelay(state.attempt) })
            } catch (err) {
              remotePollState.set(key, { attempt: state.attempt + 1, nextAt: now + kanbanRemotePollDelay(state.attempt) })
              if (card.issue !== '') {
                await storeSyncFailure(syncRecordKey(workspaceId, card.id), card.issue, err)
              }
              console.error('kanban remote completion failed for ' + card.id + ': ' + String((err && err.message) || err))
            }
          }
        }
      })().finally(() => { remoteSweepRunning = undefined })
      return remoteSweepRunning
    }

    // board.watch.list() → the live Attention Badge aggregate across every
    // registered Workspace's linked Tickets. The sidebar Kanban button polls
    // this while the Board is closed; the same poll checks remote PR/MR state.
    ctx.effect(() =>
      harness.handle('board.watch.list', async () => {
        try {
          await pollRemoteTickets()
          await sweepIssueSync()
          const tickets = []
          for (const workspace of registry.list()) {
            const workspaceId = String(workspace.id)
            for (const card of await readBoardCards({ workspaceId, workspace })) {
              const attention = cardAttention(card)
              if (attention) tickets.push({ workspaceId, ticketId: card.id, attention })
            }
          }
          tickets.sort((a, b) => a.ticketId.localeCompare(b.ticketId))
          const summary = { count: tickets.length, tickets }
          return { ok: true, count: summary.count, tickets: summary.tickets, syncRevision: issueSyncRevision }
        } catch (err) {
          return { ok: false, error: 'watch-read-failed: ' + String((err && err.message) || err) }
        }
      }),
    )

    // board.settings.list() → one durable settings record per registered
    // Workspace. Calling it also repairs any stale UUID-to-path mapping.
    ctx.effect(() =>
      harness.handle('board.settings.list', async () => {
        try {
          return { ok: true, workspaces: await enqueueSettings(syncWorkspaceSettings) }
        } catch (err) {
          return { ok: false, error: 'settings-read-failed: ' + String((err && err.message) || err) }
        }
      }),
    )

    // board.settings.update({ workspaceId, wipLimit, autopilot }) → the committed record.
    ctx.effect(() =>
      harness.handle('board.settings.update', async (args) => {
        const workspaceId = args && typeof args.workspaceId === 'string' ? args.workspaceId : ''
        if (workspaceId === '') return { ok: false, error: 'workspaceId required' }
        const wipLimit = kanbanParseWipLimit(args && args.wipLimit)
        if (wipLimit === null) return { ok: false, error: 'wipLimit must be a positive whole number' }
        const requestedAutopilot = args && args.autopilot
        if (requestedAutopilot !== undefined && typeof requestedAutopilot !== 'boolean') {
          return { ok: false, error: 'autopilot must be a boolean' }
        }
        try {
          const view = await enqueueSettings(async () => {
            const workspace = registry.get(workspaceId)
            if (workspace === undefined) return undefined
            const current = kanbanWorkspaceSettings(workspace, settingsTable.get(workspaceId))
            const settings = {
              path: workspace.path,
              wipLimit,
              autopilot: requestedAutopilot === undefined ? current.autopilot : requestedAutopilot,
            }
            await settingsTable.put(workspaceId, settings)
            return settingsView(workspace, settings)
          })
          if (view === undefined) return { ok: false, error: 'workspace-not-found' }
          return { ok: true, ...view }
        } catch (err) {
          return { ok: false, error: 'settings-write-failed: ' + String((err && err.message) || err) }
        }
      }),
    )

    const createTicketFile = async (workspace, title, body, options = {}) => {
      const dirPath = ticketsDir(workspace)
      let names = []
      const dir = await fs.resolve(dirPath)
      const info = await fs.stat(dir)
      if (info !== undefined && info.type === 'directory') {
        const entries = await fs.listDir(dir)
        names = entries.filter((entry) => entry.type === 'file').map((entry) => {
          const m = /^(kan-\d+)/i.exec(entry.name)
          return m ? m[1] : null
        })
      }
      const id = kanbanNextId(names)
      const file = id + '-' + kanbanSlug(title) + '.md'
      const text = serializeTicketFile({
        id,
        title,
        column: 'backlog',
        issue: options.issue || '',
        base: options.base,
      }, body)
      const target = await fs.resolve(dirPath + '/' + file)
      await fs.writeText(target, text, { kind: 'createIfAbsent' })
      return { id, file }
    }

    const noIssueRemoteMessage = 'No GitHub or GitLab remote exists for this Workspace.'
    const issueRemote = async (workspace) => {
      const command = (args, allowed = [0]) => kanbanRunHostCommand(shell, workspace.path, args, {
        allowedExitCodes: allowed, timeoutMs: 30000, stdoutMaxBytes: 1048576,
      })
      const issueGit = (args, allowed = [0]) => kanbanRunHostGit(shell, workspace.path, args, {
        allowedExitCodes: args.length === 1 && args[0] === 'remote' ? [0, 128] : allowed,
      })
      const remote = await kanbanDetectRemote(
        issueGit,
        (location) => kanbanProbeRemotePlatform(location, command),
      )
      return { remote, command }
    }
    const issueImportSource = async (workspace) => {
      const source = await issueRemote(workspace)
      if (source.remote.platform === 'none') return { remote: source.remote, issues: [] }
      return { remote: source.remote, issues: await kanbanIssueImportAdapter(source.remote, source.command).listOpen() }
    }
    const syncIssueColumn = async (workspaceLookup, card, column) => {
      if (card.issue === '') return
      const key = syncRecordKey(workspaceLookup.workspaceId, card.id)
      try {
        const source = await issueRemote(workspaceLookup.workspace)
        if (source.remote.platform === 'none') throw new Error('linked Issue has no supported Workspace remote')
        await kanbanIssueSyncAdapter(source.remote, source.command).setColumn(card.issue, column)
        const previous = issueSyncTable.get(key) || emptySyncRecord(card.issue)
        const at = new Date().toISOString()
        await putSyncRecord(key, {
          ...previous, issue: card.issue, error: '', lastAttemptAt: at, lastSuccessAt: at,
        })
      } catch (error) {
        await storeSyncFailure(key, card.issue, error)
      }
    }

    let issueSyncRevision = 0
    const syncRecordKey = (workspaceId, ticketId) => String(workspaceId) + '/' + String(ticketId)
    const putSyncRecord = async (key, record) => {
      const previous = issueSyncTable.get(key)
      const revisionFields = (value) => value === undefined ? null : {
        issue: value.issue, comments: value.comments, blockers: value.blockers, error: value.error,
      }
      if (JSON.stringify(revisionFields(previous)) !== JSON.stringify(revisionFields(record))) issueSyncRevision += 1
      await issueSyncTable.put(key, record)
    }
    const emptySyncRecord = (issue) => ({
      issue, comments: [], blockers: [], error: '', lastAttemptAt: '', lastSuccessAt: '',
    })
    const storeSyncFailure = async (key, issue, error, projection) => {
      const previous = issueSyncTable.get(key) || emptySyncRecord(issue)
      await putSyncRecord(key, {
        issue,
        comments: projection ? projection.comments : previous.comments,
        blockers: projection ? projection.blockers : previous.blockers,
        error: String((error && error.message) || error),
        lastAttemptAt: new Date().toISOString(),
        lastSuccessAt: previous.lastSuccessAt,
      })
    }
    const storeSyncSuccess = async (key, issue, projection) => {
      const at = new Date().toISOString()
      const record = {
        issue,
        comments: projection.comments,
        blockers: projection.blockers,
        error: '',
        lastAttemptAt: at,
        lastSuccessAt: at,
      }
      await putSyncRecord(key, record)
      return record
    }
    const refreshIssueProjection = async (workspaceLookup, card, writeBoardState = true) => {
      if (card.issue === '') return undefined
      const key = syncRecordKey(workspaceLookup.workspaceId, card.id)
      let projection
      try {
        const source = await issueRemote(workspaceLookup.workspace)
        if (source.remote.platform === 'none') throw new Error('linked Issue has no supported Workspace remote')
        const adapter = kanbanIssueSyncAdapter(source.remote, source.command)
        projection = await adapter.read(card.issue)
        if (writeBoardState) {
          await adapter.setColumn(card.issue, card.column)
          return storeSyncSuccess(key, card.issue, projection)
        }
        const previous = issueSyncTable.get(key) || emptySyncRecord(card.issue)
        const record = {
          ...previous,
          issue: card.issue,
          comments: projection.comments,
          blockers: projection.blockers,
          lastAttemptAt: new Date().toISOString(),
        }
        await putSyncRecord(key, record)
        return record
      } catch (error) {
        await storeSyncFailure(key, card.issue, error, projection)
        return issueSyncTable.get(key)
      }
    }
    const syncLinkedTicket = async (workspaceLookup, card, source) => {
      const key = syncRecordKey(workspaceLookup.workspaceId, card.id)
      let projection
      try {
        if (source.remote.platform === 'none') throw new Error('linked Issue has no supported Workspace remote')
        const adapter = kanbanIssueSyncAdapter(source.remote, source.command)
        projection = await adapter.read(card.issue)
        await enqueueMove(async () => {
          const loaded = await readTicket(ticketsDir(workspaceLookup.workspace), card.file)
          if (loaded.error !== undefined) throw new Error(loaded.error)
          const latest = parseTicketFile(card.file, loaded.text)
          if (!latest || kanbanIssueLinkKey(latest.issue) !== kanbanIssueLinkKey(card.issue)) return
          const text = kanbanApplyRemoteText(loaded.text, projection)
          if (text !== loaded.text) {
            await fs.writeText(loaded.target, text)
            issueSyncRevision += 1
          }
          const current = parseTicketFile(card.file, text)
          await adapter.setColumn(current.issue, current.column)
          if (current.column === 'done') {
            await adapter.complete(current.issue, current.reviewUrl || current.mergeSha)
          }
          await storeSyncSuccess(key, current.issue, projection)
        })
      } catch (error) {
        await storeSyncFailure(key, card.issue, error, projection)
      }
    }
    let issueSweepRunning
    const sweepIssueSync = () => {
      if (issueSweepRunning !== undefined) return issueSweepRunning
      issueSweepRunning = (async () => {
        const liveKeys = new Set()
        for (const workspace of registry.list()) {
          const workspaceId = String(workspace.id)
          const lookup = { workspaceId, workspace }
          const linked = (await readBoardCards(lookup)).filter((card) => card.issue !== '')
          if (linked.length === 0) continue
          let source
          try { source = await issueRemote(workspace) } catch (error) {
            for (const card of linked) {
              const key = syncRecordKey(workspaceId, card.id)
              liveKeys.add(key)
              await storeSyncFailure(key, card.issue, error)
            }
            continue
          }
          for (const card of linked) {
            const key = syncRecordKey(workspaceId, card.id)
            liveKeys.add(key)
            await syncLinkedTicket(lookup, card, source)
          }
        }
        for (const key of issueSyncTable.keys()) {
          if (!liveKeys.has(String(key))) {
            await issueSyncTable.delete(key)
            issueSyncRevision += 1
          }
        }
      })().finally(() => { issueSweepRunning = undefined })
      return issueSweepRunning
    }

    ctx.effect(() => {
      const timer = setInterval(() => {
        void sweepIssueSync().catch((error) => {
          console.error('kanban periodic Issue sync failed: ' + String((error && error.message) || error))
        })
      }, 30000)
      return () => clearInterval(timer)
    }, 'kanban.issueSyncTimer')

    // issue.import.list({ workspaceId }) lists open remote Issues. Linked
    // Issues remain visible with imported=true, so the dialog can explain why
    // they cannot be selected again.
    ctx.effect(() => harness.handle('issue.import.list', async (args) => {
      const lookup = workspaceOf(args)
      if (!lookup.workspace) return { ok: false, error: lookup.error }
      try {
        const source = await issueImportSource(lookup.workspace)
        if (source.remote.platform === 'none') {
          return { ok: true, platform: 'none', issues: [], message: noIssueRemoteMessage }
        }
        const tickets = await readBoardCards(lookup)
        return {
          ok: true,
          platform: source.remote.platform,
          issues: kanbanMarkImportedIssues(source.issues, tickets),
        }
      } catch (err) {
        return { ok: false, error: 'issue-import-list-failed: ' + String((err && err.message) || err) }
      }
    }))

    // issue.import.create({ workspaceId, numbers }) re-reads the remote list,
    // accepts only selected open Issue numbers, and creates Backlog Ticket
    // Files. A linked or unavailable Issue is skipped without another write.
    ctx.effect(() => harness.handle('issue.import.create', async (args) => {
      const lookup = workspaceOf(args)
      if (!lookup.workspace) return { ok: false, error: lookup.error }
      const numbers = Array.from(new Set((Array.isArray(args && args.numbers) ? args.numbers : [])
        .map((number) => Number(number)).filter((number) => Number.isSafeInteger(number) && number > 0)))
      try {
        return await enqueueMove(async () => {
          const source = await issueImportSource(lookup.workspace)
          if (source.remote.platform === 'none') {
            return { ok: true, platform: 'none', imported: [], skipped: numbers, message: noIssueRemoteMessage }
          }
          const available = new Map(source.issues.map((issue) => [issue.number, issue]))
          const linked = new Set((await readBoardCards(lookup))
            .map((ticket) => kanbanIssueLinkKey(ticket.issue)).filter(Boolean))
          const imported = []
          const skipped = []
          for (const number of numbers) {
            const issue = available.get(number)
            const issueLink = kanbanIssueLinkKey(issue && issue.url)
            if (!issue || issue.title.trim() === '' || issueLink === '' || linked.has(issueLink)) {
              skipped.push(number)
              continue
            }
            const ticket = await createTicketFile(lookup.workspace, issue.title.trim(), issue.body, { issue: issue.url })
            imported.push({ number, ...ticket })
            linked.add(issueLink)
          }
          return { ok: true, platform: source.remote.platform, imported, skipped }
        })
      } catch (err) {
        return { ok: false, error: 'issue-import-create-failed: ' + String((err && err.message) || err) }
      }
    }))

    // ticket.create({ workspaceId, title, body }) → a new Ticket File in the
    // backlog column. The id continues the highest existing KAN number
    // (KAN-101 when the Board is empty); the file name is <id>-<slug>.md.
    ctx.effect(() =>
      harness.handle('ticket.create', async (args) => {
        const workspaceLookup = workspaceOf(args)
        if (workspaceLookup.workspace === undefined) return { ok: false, error: workspaceLookup.error }
        const title = String((args && args.title) || '').trim()
        if (title === '') return { ok: false, error: 'title required' }
        const body = String((args && args.body) || '')
        const base = args && args.base === 'head' ? 'head' : undefined
        try {
          return { ok: true, ...await createTicketFile(workspaceLookup.workspace, title, body, { base }) }
        } catch (err) {
          return { ok: false, error: 'ticket-create-failed: ' + String((err && err.message) || err) }
        }
      }),
    )

    // ticket.update({ workspaceId, file, title, body, blocked, base }) →
    // rewrites title, blocked, base and body via surgical patches, so every
    // other frontmatter field (issue, branch, linkage, unknown keys)
    // stays byte-identical. An empty blocked value clears the badge.
    ctx.effect(() =>
      harness.handle('ticket.update', async (args) => {
        const workspaceLookup = workspaceOf(args)
        if (workspaceLookup.workspace === undefined) return { ok: false, error: workspaceLookup.error }
        const title = String((args && args.title) || '').trim()
        if (title === '') return { ok: false, error: 'title required' }
        const dirPath = ticketsDir(workspaceLookup.workspace)
        try {
          // Share the move tail so a description edit cannot overwrite a
          // concurrent Bounce's column or history with an earlier file read.
          return await enqueueMove(async () => {
            const loaded = await readTicket(dirPath, String((args && args.file) || ''))
            if (loaded.error !== undefined) return { ok: false, error: loaded.error }
            const card = parseTicketFile(String(args.file), loaded.text)
            if (card === null) return { ok: false, error: 'not-a-ticket-file' }
            const blocked = String((args && args.blocked) || '').trim()
            const ownedTitle = card.issue === '' ? title : card.title
            const ownedBody = card.issue === '' ? String((args && args.body) || '') : card.body
            let text = kanbanSetAttr(loaded.text, 'title', ownedTitle)
            text = kanbanSetAttr(text, 'blocked', blocked === '' ? null : blocked)
            text = kanbanSetAttr(text, 'base', args && args.base === 'head' ? 'head' : null)
            text = kanbanSetBody(text, ownedBody)
            if (text === null) return { ok: false, error: 'not-a-ticket-file' }
            await fs.writeText(loaded.target, text)
            return { ok: true, file: String(args.file) }
          })
        } catch (err) {
          return { ok: false, error: 'ticket-update-failed: ' + String((err && err.message) || err) }
        }
      }),
    )

    let refinementSequence = 0
    // ticket.refine({ workspaceId, file }) starts a Refinement Session only
    // when the external skill is model-invocable for this Workspace. The Host
    // never writes the Ticket File or creates a Worktree during this action.
    ctx.effect(() =>
      harness.handle('ticket.refine', async (args) => {
        const workspaceLookup = workspaceOf(args)
        if (workspaceLookup.workspace === undefined) return { ok: false, error: workspaceLookup.error }
        const file = String((args && args.file) || '')
        let handle
        try {
          return await enqueueMove(async () => {
          const loaded = await readTicket(ticketsDir(workspaceLookup.workspace), file)
          if (loaded.error !== undefined) return { ok: false, error: loaded.error }
          const card = parseTicketFile(file, loaded.text)
          if (card === null) return { ok: false, error: 'not-a-ticket-file' }
          if (card.column !== 'backlog') return { ok: false, error: 'ticket-not-in-backlog' }
          if (card.issue !== '') return { ok: false, error: 'linked-ticket-text-owned-by-issue' }

          const catalog = await skills.list({ cwd: workspaceLookup.workspace.path })
          const available = catalog.some((skill) =>
            skill.name === 'grill-with-docs' && skill.invocation && skill.invocation.modelInvocable === true)
          if (!available) {
            return {
              ok: false,
              error: 'Install the external `grill-with-docs` skill with model invocation enabled before starting a Refinement Session.',
            }
          }

          const workspacePath = workspaceLookup.workspace.path.replace(/\/+$/, '')
          const ticketFrontmatter = loaded.text.slice(0, loaded.text.length - card.body.length)
          let refinementBody = card.body
          const sessionId = ('kanban-refine-' + workspaceLookup.workspaceId + '-' + card.id + '-' +
            Date.now() + '-' + (++refinementSequence)).toLowerCase().replace(/[^a-z0-9_-]+/g, '-')
          const selection = agentDefaultModel.currentSelection()
          const preset = await agentPresets.resolve()
          handle = await agents.create({
            sessionId,
            meta: { cwd: workspacePath, agentPreset: preset.id },
            agentOptions: { provider: selection.provider, model: selection.model },
            setup: async (agentCtx) => {
              await agentPresets.mount(agentCtx, preset.id)
              const tools = agentCtx.get('tools')
              if (tools === undefined) throw new Error('Refinement Session tools are unavailable')
              tools.restrict({ allow: ['skill', 'read', 'edit'] })
              tools.guard((execution) => {
                if (execution.name === 'run_code') return undefined
                if (!['skill', 'read', 'edit'].includes(execution.name)) {
                  return 'Refinement Sessions can only load the skill and edit their Ticket File.'
                }
                const args = execution.arguments && typeof execution.arguments === 'object' ? execution.arguments : {}
                if (execution.name === 'skill' && args.name !== 'grill-with-docs') {
                  return 'This Refinement Session can only load grill-with-docs.'
                }
                if ((execution.name === 'read' || execution.name === 'edit') && args.file_path !== loaded.target) {
                  return 'This Refinement Session can only access ' + loaded.target
                }
                if (execution.name === 'edit') {
                  if (typeof args.old_string !== 'string' || args.old_string === '' ||
                      !refinementBody.includes(args.old_string) || ticketFrontmatter.includes(args.old_string)) {
                    return 'This Refinement Session can only replace content from the Ticket File body.'
                  }
                  if (typeof args.new_string === 'string') {
                    const count = refinementBody.split(args.old_string).length - 1
                    if (args.replace_all === true) refinementBody = refinementBody.split(args.old_string).join(args.new_string)
                    else if (count === 1) refinementBody = refinementBody.replace(args.old_string, args.new_string)
                  }
                }
                return undefined
              })
            },
          })
          rememberSession(handle)
          await handle.agent.whenIdle()
          const brief = [
            'Refine ' + card.id + ' by using the external `grill-with-docs` skill.',
            '',
            'First, call the `skill` tool with `grill-with-docs`. Follow its instructions completely.',
            'Interview the user to extract the goal, context, and acceptance criteria.',
            '',
            'Refinement rules:',
            '- Work in the plain Workspace `' + workspacePath + '`.',
            '- Read and write only the Ticket File `' + loaded.target + '`.',
            '- Do not create, edit, rename, or delete any other file.',
            '- Preserve the Ticket File frontmatter exactly.',
            '- The Ticket must remain in Backlog. Only the user may move it to Ready.',
            '- Do not create or use a Worktree, branch, or commit.',
            '- After the interview, write the enriched goal, context, and acceptance criteria into the Ticket File body.',
            '- Keep the markdown human-readable so the user can review its diff before moving the Ticket.',
            '',
            'Current Ticket File:',
            '',
            loaded.text,
          ].join('\n')
          handle.agent.followup({
            id: 'kanban-refine-brief-' + sessionId,
            role: 'user',
            content: [{ type: 'text', text: brief }],
            source: { kind: 'plugin', plugin: 'dsh-kanban' },
          })
          return { ok: true, sessionId }
          })
        } catch (err) {
          if (handle !== undefined) {
            try { await handle.dispose() } catch {}
            if (handle.agent) sessionHandles.delete(handle.agent.id)
          }
          return { ok: false, error: 'ticket-refine-failed: ' + String((err && err.message) || err) }
        }
      }),
    )

    ctx.effect(() => harness.handle('ticket.review', async (args) => {
      const lookup = workspaceOf(args)
      if (!lookup.workspace) return { ok: false, error: lookup.error }
      try {
        return await enqueueMove(async () => {
          const file = String((args && args.file) || '')
          const loaded = await readTicket(ticketsDir(lookup.workspace), file)
          if (loaded.error) throw new Error(loaded.error)
          const card = parseTicketFile(file, loaded.text)
          if (card && card.issue !== '') throw new Error('linked-ticket-requires-remote-completion')
          return { ok: true, ...await kanbanLocalReview({ file, text: loaded.text, workspacePath: lookup.workspace.path }, completionGit(lookup.workspace)) }
        })
      } catch (error) { return { ok: false, error: 'ticket-review-failed: ' + String(error.message || error) } }
    }))

    ctx.effect(() => harness.handle('ticket.accept', async (args) => {
      const lookup = workspaceOf(args)
      if (!lookup.workspace) return { ok: false, error: lookup.error }
      try {
        return await enqueueMove(async () => {
          const file = String((args && args.file) || '')
          const loaded = await readTicket(ticketsDir(lookup.workspace), file)
          if (loaded.error) throw new Error(loaded.error)
          const card = parseTicketFile(file, loaded.text)
          if (card && card.issue !== '') throw new Error('linked-ticket-requires-remote-completion')
          const agent = agents.get(card.sessionId)
          let handle
          if (agent !== undefined) {
            if (agent.status !== 'idle') throw new Error('session-not-idle')
            handle = sessionHandles.get(card.sessionId)
            if (!handle || handle.agent !== agent) throw new Error('session-not-owned-by-board')
          }
          const result = await kanbanAcceptLocalTicket({ file, text: loaded.text, workspacePath: lookup.workspace.path, review: args.review }, {
            git: completionGit(lookup.workspace),
            persistTicket: (text) => fs.writeText(loaded.target, text),
            async releaseSession() {
              if (!handle) return
              await handle.dispose()
              sessionHandles.delete(card.sessionId)
            },
          })
          await executionTable.delete(lookup.workspaceId + '/' + card.id)
          invalidateWatch(card.sessionId)
          await pumpQueue(lookup).catch(logPumpFailure)
          return { ok: true, ...result }
        })
      } catch (error) { return { ok: false, error: 'ticket-accept-failed: ' + String(error.message || error) } }
    }))

    let recoverySequence = 0
    const recoveryTicket = async (workspaceLookup, file) => {
      const loaded = await readTicket(ticketsDir(workspaceLookup.workspace), file)
      if (loaded.error) throw new Error(loaded.error)
      const card = parseTicketFile(file, loaded.text)
      if (card.column !== 'in-progress' || kanbanIsQueued(card) || cardAttention(card) !== 'error') {
        throw new Error('ticket-not-stalled')
      }
      if (!card.sessionId || !card.branch || !card.worktreePath) throw new Error('ticket-not-started')
      const slug = /^kan-\d+-([a-z0-9-]+)\.md$/i.exec(file)[1]
      const root = workspaceLookup.workspace.path.replace(/\/+$/, '')
      if (card.worktreePath !== root + '/.dsh-kanban/worktrees/' + slug ||
          card.branch !== 'kanban/' + card.id + '-' + slug) throw new Error('unsafe-execution-linkage')
      const agent = agents.get(card.sessionId)
      if (agent !== undefined && agent.status !== 'idle') throw new Error('session-not-idle')
      return { loaded, card, agent }
    }

    ctx.effect(() => harness.handle('ticket.resume', async (args) => {
      const lookup = workspaceOf(args)
      if (!lookup.workspace) return { ok: false, error: lookup.error }
      try {
        return await enqueueMove(async () => {
          let { card, agent } = await recoveryTicket(lookup, String((args && args.file) || ''))
          if (!agent) {
            const handle = await agents.resume({
              resumeSessionId: card.sessionId,
              setup: (agentCtx) => agentPresets.mount(agentCtx, agentCtx.agent.session.header.agentPreset),
            })
            rememberSession(handle)
            try {
              await handle.agent.whenIdle()
              if (handle.agent.session.header.cwd !== card.worktreePath) throw new Error('session-worktree-mismatch')
              agent = handle.agent
            } catch (error) {
              await handle.dispose()
              sessionHandles.delete(card.sessionId)
              throw error
            }
          }
          if (agents.get(card.sessionId) !== agent || agent.status !== 'idle') throw new Error('session-not-idle')
          agent.steer({
            id: 'kanban-resume-' + card.sessionId + '-' + Date.now() + '-' + (++recoverySequence),
            role: 'user', content: [{ type: 'text', text: 'Continue the Ticket from where you stopped. Keep existing work and commit the completed result.' }],
          })
          invalidateWatch(card.sessionId)
          return { ok: true, sessionId: card.sessionId }
        })
      } catch (err) {
        return { ok: false, error: 'ticket-resume-failed: ' + String((err && err.message) || err) }
      }
    }))

    ctx.effect(() => harness.handle('ticket.retry', async (args) => {
      const lookup = workspaceOf(args)
      if (!lookup.workspace) return { ok: false, error: lookup.error }
      try {
        return await enqueueMove(async () => {
          const file = String((args && args.file) || '')
          const { loaded, card, agent } = await recoveryTicket(lookup, file)
          const git = (args) => watchRunGit(lookup.workspace.path, ['-C', card.worktreePath, ...args])
          if (await git(['rev-parse', '--show-toplevel']) !== card.worktreePath ||
              await git(['symbolic-ref', '--short', 'HEAD']) !== card.branch) throw new Error('worktree-linkage-mismatch')
          if (agent && (agents.get(card.sessionId) !== agent || agent.status !== 'idle')) throw new Error('session-not-idle')
          if (agent) {
            const handle = sessionHandles.get(card.sessionId)
            if (!handle || handle.agent !== agent) throw new Error('session-not-owned-by-board')
            await handle.dispose()
            sessionHandles.delete(card.sessionId)
          }
          invalidateWatch(card.sessionId)
          const adapter = kanbanHostExecutionAdapter({
            workspace: lookup.workspace, loaded, fs, shell, agents, rememberSession,
            agentDefaultModel, agentPresets, executionTable, setTicketAttr: kanbanSetAttr,
          })
          const sessionId = 'kanban-retry-' + card.id.toLowerCase() + '-' + Date.now() + '-' + (++recoverySequence)
          const key = lookup.workspaceId + '/' + card.id
          const previous = executionTable.get(key)
          let session
          try {
            session = await adapter.createSession({
              sessionId,
              cwd: card.worktreePath,
              autopilot: autopilotFor(lookup),
            })
            await adapter.persistTicket(kanbanSetAttr(loaded.text, 'sessionId', sessionId))
            await adapter.persistLinkage(key, {
              workspaceId: lookup.workspaceId, ticketId: card.id, sessionId,
              branch: card.branch, worktreePath: card.worktreePath, baseSha: previous ? previous.baseSha : '',
            })
            await adapter.followup(session,
              'Continue the Ticket. Inspect and preserve existing work in this Worktree before making changes.\n\n' +
              kanbanExecutionBrief(loaded.text, card.branch, lookup.workspace.path, card.worktreePath))
            return { ok: true, sessionId }
          } catch (error) {
            const failures = []
            for (const operation of [
              () => session && adapter.disposeSession(session),
              () => adapter.persistTicket(loaded.text),
              () => previous ? adapter.persistLinkage(key, previous) : adapter.deleteLinkage(key),
            ]) {
              try { await operation() } catch (failure) { failures.push(String(failure.message || failure)) }
            }
            watchAttention.set(card.sessionId, 'error')
            watchMessages.set(card.sessionId, 'Retry fresh failed: ' + String(error.message || error))
            throw new Error(String(error.message || error) + (failures.length ? '; rollback failed: ' + failures.join('; ') : ''))
          }
        })
      } catch (err) {
        return { ok: false, error: 'ticket-retry-failed: ' + String((err && err.message) || err) }
      }
    }))

    const cleanupConfirmations = new Map()
    ctx.effect(() => harness.handle('ticket.sendBack', async (args) => {
      const lookup = workspaceOf(args)
      if (!lookup.workspace) return { ok: false, error: lookup.error }
      try {
        return await enqueueMove(async () => {
          const file = String((args && args.file) || '')
          const { loaded, card, agent } = await recoveryTicket(lookup, file)
          const root = lookup.workspace.path.replace(/\/+$/, '')
          const handle = agent && sessionHandles.get(card.sessionId)
          if (agent && (!handle || handle.agent !== agent)) throw new Error('session-not-owned-by-board')
          const git = (args) => watchRunGit(root, args)
          const worktree = ['-C', card.worktreePath]
          if (await git([...worktree, 'rev-parse', '--show-toplevel']) !== card.worktreePath ||
              await git([...worktree, 'symbolic-ref', '--short', 'HEAD']) !== card.branch) throw new Error('worktree-linkage-mismatch')
          if (await git([...worktree, 'status', '--porcelain', '--untracked-files=all', '--ignored']) !== '') {
            throw new Error('worktree-not-clean: preserve or remove uncommitted and ignored files before sending back')
          }
          const head = await git(['rev-parse', '--verify', 'refs/heads/' + card.branch])
          const base = await git(['rev-parse', '--verify', 'HEAD'])
          const unmergedCommits = Number(await git(['rev-list', '--count', base + '..' + head]))
          if (!Number.isSafeInteger(unmergedCommits) || unmergedCommits < 0) throw new Error('invalid-commit-count')
          const key = lookup.workspaceId + '/' + card.id
          const snapshot = [card.sessionId, card.branch, card.worktreePath, head, base].join('\n')
          const pending = cleanupConfirmations.get(key)
          if (unmergedCommits > 0 && (!pending || pending.snapshot !== snapshot || args.confirmation !== pending.token)) {
            const token = 'cleanup-' + Date.now() + '-' + (++recoverySequence)
            cleanupConfirmations.set(key, { token, snapshot })
            return { ok: false, confirmationRequired: true, confirmation: token, unmergedCommits,
              error: 'Delete ' + unmergedCommits + ' commits not merged into Workspace HEAD, and remove the Worktree?' }
          }
          if (agent && (agents.get(card.sessionId) !== agent || agent.status !== 'idle')) throw new Error('session-not-idle')
          if (handle) { await handle.dispose(); sessionHandles.delete(card.sessionId) }
          invalidateWatch(card.sessionId)
          const previous = executionTable.get(key)
          let removed = false
          let branchDeleted = false
          let text = loaded.text
          for (const [name, value] of [['column', 'ready'], ['sessionId', null], ['worktreePath', null], ['branch', null], ['queued', null]]) {
            text = kanbanSetAttr(text, name, value)
          }
          try {
            await git(['worktree', 'remove', card.worktreePath])
            removed = true
            // Delete only the exact confirmed head; a concurrent commit fails closed.
            await git(['update-ref', '-d', 'refs/heads/' + card.branch, head])
            branchDeleted = true
            await fs.writeText(loaded.target, text)
            await executionTable.delete(key)
          } catch (error) {
            const failures = []
            const restore = async (operation) => {
              try { await operation() } catch (failure) { failures.push(String(failure.message || failure)) }
            }
            if (branchDeleted) await restore(() => git(['branch', card.branch, head]))
            if (removed) await restore(() => git(['worktree', 'add', card.worktreePath, card.branch]))
            await restore(() => fs.writeText(loaded.target, loaded.text))
            if (previous) await restore(() => executionTable.put(key, previous))
            watchAttention.set(card.sessionId, 'error')
            watchMessages.set(card.sessionId, 'Send back failed: ' + String(error.message || error))
            throw new Error(String(error.message || error) + (failures.length ? '; rollback failed: ' + failures.join('; ') : ''))
          }
          cleanupConfirmations.delete(key)
          await syncIssueColumn(lookup, card, 'ready')
          await pumpQueue(lookup).catch(logPumpFailure)
          return { ok: true, column: 'ready' }
        })
      } catch (err) {
        return { ok: false, error: 'ticket-send-back-failed: ' + String((err && err.message) || err) }
      }
    }))

    let bounceSequence = 0
    ctx.effect(() =>
      harness.handle('ticket.bounce', async (args) => {
        const workspaceLookup = workspaceOf(args)
        if (workspaceLookup.workspace === undefined) return { ok: false, error: workspaceLookup.error }
        const file = String((args && args.file) || '')
        try {
          return await enqueueMove(async () => {
            const loaded = await readTicket(ticketsDir(workspaceLookup.workspace), file)
            if (loaded.error !== undefined) return { ok: false, error: loaded.error }
            const at = new Date().toISOString()
            const result = await kanbanBounceTicket(
              { file, ticketText: loaded.text, comment: args && args.comment, at },
              {
                liveAgent: (sessionId) => agents.get(sessionId),
                persistTicket: (text) => fs.writeText(loaded.target, text),
                steer(agent, comment) {
                  agent.steer({
                    id: 'kanban-bounce-' + agent.id + '-' + at + '-' + (++bounceSequence),
                    role: 'user',
                    content: [{ type: 'text', text: comment }],
                  })
                  invalidateWatch(agent.id)
                },
              },
            )
            const card = parseTicketFile(file, loaded.text)
            await syncIssueColumn(workspaceLookup, card, result.column)
            return { ok: true, ...result }
          })
        } catch (err) {
          return { ok: false, error: 'ticket-bounce-failed: ' + String((err && err.message) || err) }
        }
      }),
    )

    // ticket.move({ workspaceId, file, column }) moves a Ticket and drives
    // the WIP queue: over-limit Ready → In Progress enqueues, moves that
    // free a slot auto-spawn the earliest queued Ticket, and a queued
    // Ticket moved anywhere drops its queue marker (manual dequeue is the
    // move back to Ready). Moves serialize behind one tail.
    ctx.effect(() =>
      harness.handle('ticket.move', async (args) => {
        const workspaceLookup = workspaceOf(args)
        if (workspaceLookup.workspace === undefined) return { ok: false, error: workspaceLookup.error }
        const column = String((args && args.column) || '').trim().toLowerCase()
        if (!KANBAN_COLUMNS.includes(column)) return { ok: false, error: 'invalid-column' }
        const file = String((args && args.file) || '')
        try {
          return await enqueueMove(() => moveTicket(workspaceLookup, file, column))
        } catch (err) {
          return { ok: false, error: 'ticket-move-failed: ' + String((err && err.message) || err) }
        }
      }),
    )
  },
}
}

const definition = createKanbanPlugin(() => () => {})

export const name = 'kanban'
export const inject = [...definition.inject, 'typert']

export async function apply(ctx) {
  const handlers = new Map()
  const register = (method, handler) => {
    if (handlers.has(method)) throw new Error('dsh-kanban: duplicate Host method ' + method)
    handlers.set(method, handler)
    return () => handlers.delete(method)
  }
  const plugin = createKanbanPlugin(register)
  await plugin.apply(ctx)
  new KanbanGateway(ctx, createKanbanController(handlers))
}
